macro_rules! standalone_hud_texture_upload {
    ($method:ident => $field:ident) => {
        pub fn $method(
            &mut self,
            width: u32,
            height: u32,
            rgba: &[u8],
            sampling: StandaloneTextureSampling,
        ) -> Result<()> {
            self.$field = Some(self.upload_standalone_hud_sprite(width, height, rgba, sampling)?);
            Ok(())
        }
    };
}

pub const HUD_HOTBAR_SLOTS: usize = 9;
/// Vanilla `Options.textBackgroundOpacity` default
/// (`options.accessibility.text_background_opacity`).
pub const VANILLA_DEFAULT_TEXT_BACKGROUND_OPACITY: f32 = 0.5;

/// Nine-slice scaling metadata for a HUD sprite, mirroring vanilla `GuiSpriteScaling.NineSlice`
/// (`assets/.../gui/sprites/**.png.mcmeta` → `gui.scaling`). `sprite_width`/`sprite_height` are the
/// declared nine-slice grid size (the sprite is uploaded as its own texture, so UVs are direct
/// fractions of these), the four borders are per-edge slice widths, and `stretch_inner` selects
/// stretch (`true`) vs tile (`false`) for the four edge slices and the center.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HudNineSliceScaling {
    pub sprite_width: u32,
    pub sprite_height: u32,
    pub border_left: u32,
    pub border_top: u32,
    pub border_right: u32,
    pub border_bottom: u32,
    pub stretch_inner: bool,
}

/// GUI sprite scaling selected by `assets/.../gui/sprites/**.png.mcmeta`, matching vanilla
/// `GuiSpriteScaling`. Custom tooltip background and frame sprites can independently use any of
/// the three variants.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum HudGuiSpriteScaling {
    Stretch,
    Tile { width: u32, height: u32 },
    NineSlice(HudNineSliceScaling),
}

#[cfg(test)]
mod chat_layout_tests {
    use super::*;

    fn glyphs_for(text: &str) -> HudFontGlyphMap {
        let mut glyphs = HudFontGlyphMap::new();
        let glyph = HudAsciiGlyph {
            width: 5,
            height: 8,
            advance: 6,
            ..HudAsciiGlyph::default()
        };
        for ch in text.chars().chain(std::iter::once('?')) {
            glyphs.insert_first_wins(ch, glyph);
        }
        glyphs
    }

    #[test]
    fn rich_chat_wrap_preserves_run_style_and_word_boundary() {
        let glyphs = glyphs_for("alpha beta");
        let bold = HudTextStyle {
            bold: true,
            ..HudTextStyle::default()
        };
        let lines = hud_wrap_chat_runs(
            &[
                HudStyledTextRun::plain("alpha "),
                HudStyledTextRun {
                    text: "beta".to_string(),
                    style: bold,
                    color: Some(0x55ffff),
                },
            ],
            36,
            &glyphs,
        );
        assert_eq!(lines.len(), 2);
        assert_eq!(lines[0], vec![HudStyledTextRun::plain("alpha")]);
        assert_eq!(lines[1][0].text, "beta");
        assert_eq!(lines[1][0].style, bold);
        assert_eq!(lines[1][0].color, Some(0x55ffff));
    }

    #[test]
    fn modified_tag_reserves_icon_width_before_wrapping() {
        let text = "a".repeat(52);
        let glyphs = glyphs_for(&text);
        let plain = HudChatMessage {
            display_sequence: 1,
            added_tick: 0,
            runs: vec![HudComponentTextRun::plain(&text)],
            interactions: Vec::new(),
            tag: None,
        };
        let modified = HudChatMessage {
            tag: Some(HudChatTag {
                kind: HudChatTagKind::Modified,
                indicator_color: 6_316_128,
                tooltip_runs: Vec::new(),
            }),
            ..plain.clone()
        };
        let fonts = HudFontGlyphBook::from(glyphs);
        assert_eq!(hud_wrap_chat_messages(&[plain], &fonts).len(), 1);
        assert_eq!(hud_wrap_chat_messages(&[modified], &fonts).len(), 2);
    }

    #[test]
    fn chat_alpha_matches_vanilla_focus_and_two_hundred_tick_fade() {
        let line = HudChatLine {
            display_sequence: 1,
            added_tick: 10,
            runs: vec![HudComponentTextRun::plain("hello")],
            tag: None,
            interactions: Vec::new(),
            end_of_entry: true,
        };
        let mut context = HudChatContext {
            gui_ticks: 200,
            ..HudChatContext::default()
        };
        assert!((hud_chat_line_alpha(&context, &line) - 0.25).abs() < 1.0e-6);
        context.gui_ticks = 210;
        assert_eq!(hud_chat_line_alpha(&context, &line), 0.0);
        context.focused = true;
        assert_eq!(hud_chat_line_alpha(&context, &line), 1.0);
    }

    #[test]
    fn chat_interaction_follows_wrapped_glyph_spans() {
        let text = format!("{} beta", "a".repeat(52));
        let glyphs = glyphs_for(&text);
        let message = HudChatMessage {
            display_sequence: 7,
            added_tick: 0,
            runs: vec![HudComponentTextRun::plain(&text)],
            interactions: vec![HudChatInteraction {
                start_char: 53,
                end_char: 57,
                target_index: 3,
                insertion: false,
                tooltip: None,
            }],
            tag: None,
        };
        let fonts = HudFontGlyphBook::from(glyphs);
        let lines = hud_wrap_chat_messages(&[message], &fonts);
        assert_eq!(lines.len(), 2);
        assert_eq!(lines[1].interactions.len(), 1);
        assert_eq!(lines[1].interactions[0].start_x, 0);
        assert_eq!(lines[1].interactions[0].end_x, 24);

        let context = HudChatContext {
            level_generation: 11,
            delivery_revision: 13,
            chat_screen_revision: 19,
            resource_generation: 17,
            resources_loaded: true,
            focused: true,
            ..HudChatContext::default()
        };
        let hit = hud_chat_hit_target_at(
            &lines,
            &context,
            &fonts,
            PhysicalSize::new(800, 600),
            (5.0, 552.0),
        );
        assert_eq!(
            hit,
            Some(HudChatHitTarget {
                level_generation: 11,
                delivery_revision: 13,
                chat_screen_revision: 19,
                resource_generation: 17,
                resources_loaded: true,
                kind: HudChatHitTargetKind::Message {
                    display_sequence: 7,
                    target_index: 3,
                },
            })
        );
    }

    #[test]
    fn chat_interactions_follow_visual_rtl_glyph_spans_after_logical_wrap() {
        let mut glyphs = glyphs_for("אב");
        glyphs.set_default_right_to_left(true);
        let lines = hud_wrap_chat_runs_with_interactions(
            &[HudStyledTextRun::plain("אב")],
            &[
                HudChatInteraction {
                    start_char: 0,
                    end_char: 1,
                    target_index: 1,
                    insertion: false,
                    tooltip: None,
                },
                HudChatInteraction {
                    start_char: 1,
                    end_char: 2,
                    target_index: 2,
                    insertion: false,
                    tooltip: None,
                },
            ],
            100,
            &glyphs,
        );

        assert_eq!(lines.len(), 1);
        assert_eq!(lines[0].runs, vec![HudStyledTextRun::plain("אב")]);
        assert_eq!(
            lines[0]
                .interactions
                .iter()
                .map(|interaction| (
                    interaction.start_x,
                    interaction.end_x,
                    interaction.target_index
                ))
                .collect::<Vec<_>>(),
            vec![(0, 6, 2), (6, 12, 1)]
        );
    }

    #[test]
    fn hud_chat_custom_font_controls_wrapping_and_interaction_width() {
        let default = glyphs_for("a");
        let mut compact = HudFontGlyphMap::new();
        compact.insert_first_wins(
            'a',
            HudAsciiGlyph {
                width: 1,
                height: 8,
                advance: 2,
                ..HudAsciiGlyph::default()
            },
        );
        let fonts = HudFontGlyphBook::from_fonts(
            "minecraft:default",
            BTreeMap::from([
                ("example:compact".to_string(), compact),
                ("minecraft:default".to_string(), default),
            ]),
        );
        let text = "a".repeat(10);
        let lines = hud_wrap_component_runs_with_interactions(
            &[HudComponentTextRun {
                visual: HudStyledTextRun::plain(&text),
                font: Some("example:compact".to_string()),
            }],
            &[HudChatInteraction {
                start_char: 0,
                end_char: text.chars().count(),
                target_index: 7,
                insertion: false,
                tooltip: None,
            }],
            20,
            &fonts,
        );

        assert_eq!(lines.len(), 1);
        assert_eq!(lines[0].runs[0].font.as_deref(), Some("example:compact"));
        assert_eq!(lines[0].interactions[0].start_x, 0);
        assert_eq!(lines[0].interactions[0].end_x, 20);
    }

    #[test]
    fn hud_chat_accumulates_unihex_half_pixel_bold_advance_before_rounding() {
        let mut glyphs = HudFontGlyphMap::new();
        glyphs.insert_first_wins(
            '中',
            HudAsciiGlyph {
                width: 16,
                height: 16,
                advance: 9,
                render_scale: 0.5,
                bold_offset: 0.5,
                shadow_offset: 0.5,
                ..HudAsciiGlyph::default()
            },
        );
        let runs = [HudComponentTextRun {
            visual: HudStyledTextRun {
                text: "中中".to_string(),
                style: HudTextStyle {
                    bold: true,
                    ..HudTextStyle::default()
                },
                color: None,
            },
            font: None,
        }];
        let lines = hud_wrap_component_runs_with_interactions(
            &runs,
            &[HudChatInteraction {
                start_char: 0,
                end_char: 2,
                target_index: 9,
                insertion: false,
                tooltip: None,
            }],
            19,
            &HudFontGlyphBook::from(glyphs),
        );

        assert_eq!(lines.len(), 1);
        assert_eq!(lines[0].interactions[0].start_x, 0);
        assert_eq!(lines[0].interactions[0].end_x, 19);
    }

    #[test]
    fn hud_chat_unavailable_font_falls_back_to_default_glyphs() {
        let fonts = HudFontGlyphBook::from(glyphs_for("a"));
        let text = "a".repeat(10);
        let lines = hud_wrap_component_runs_with_interactions(
            &[HudComponentTextRun {
                visual: HudStyledTextRun::plain(&text),
                font: Some("example:missing".to_string()),
            }],
            &[HudChatInteraction {
                start_char: 0,
                end_char: text.chars().count(),
                target_index: 3,
                insertion: false,
                tooltip: None,
            }],
            20,
            &fonts,
        );

        assert_eq!(lines.len(), 4);
        assert_eq!(lines[0].runs[0].visual.text, "aaa");
        assert_eq!(lines[0].interactions[0].end_x, 18);
    }

    #[test]
    fn hud_chat_space_provider_glyph_advances_without_a_bitmap() {
        let mut default = glyphs_for("?");
        default.insert_first_wins(
            '\u{200c}',
            HudAsciiGlyph {
                width: 0,
                height: 0,
                advance: 9,
                ..HudAsciiGlyph::default()
            },
        );
        let lines = hud_wrap_component_runs_with_interactions(
            &[HudComponentTextRun::plain("\u{200c}")],
            &[HudChatInteraction {
                start_char: 0,
                end_char: 1,
                target_index: 5,
                insertion: false,
                tooltip: None,
            }],
            20,
            &HudFontGlyphBook::from(default),
        );

        assert_eq!(lines.len(), 1);
        assert_eq!(lines[0].interactions[0].start_x, 0);
        assert_eq!(lines[0].interactions[0].end_x, 9);
    }

    #[test]
    fn hud_chat_entity_hover_lines_require_advanced_tooltips() {
        let tooltip = HudRichTooltip {
            style: None,
            lines: Vec::new(),
            advanced_lines: Some(vec![HudRichTooltipLine::plain("Type: minecraft:pig")]),
            wrap_text: false,
        };

        assert!(hud_rich_tooltip_lines(&tooltip, false).is_empty());
        assert_eq!(
            hud_rich_tooltip_lines(&tooltip, true)[0].runs[0]
                .visual
                .text,
            "Type: minecraft:pig"
        );
    }

    #[test]
    fn queue_hit_is_focused_and_revision_bound() {
        let context = HudChatContext {
            level_generation: 2,
            delivery_revision: 5,
            focused: true,
            queued_messages: 1,
            ..HudChatContext::default()
        };
        let fonts = HudFontGlyphBook::default();
        let hit = hud_chat_hit_target_at(
            &[],
            &context,
            &fonts,
            PhysicalSize::new(800, 600),
            (4.0, 561.0),
        );
        assert_eq!(hit.map(|hit| hit.kind), Some(HudChatHitTargetKind::Queue));
        let unfocused = HudChatContext {
            focused: false,
            ..context
        };
        assert!(hud_chat_hit_target_at(
            &[],
            &unfocused,
            &fonts,
            PhysicalSize::new(800, 600),
            (4.0, 561.0),
        )
        .is_none());
    }

    #[test]
    fn restricted_chat_prompt_and_done_button_are_revision_bound_targets() {
        let text = "Chat is restricted";
        let fonts = HudFontGlyphBook::from(glyphs_for(text));
        let context = HudChatContext {
            level_generation: 2,
            delivery_revision: 5,
            chat_screen_revision: 7,
            focused: true,
            restricted_text: Some(text.to_string()),
            ..HudChatContext::default()
        };
        let prompt = hud_chat_hit_target_at(
            &[],
            &context,
            &fonts,
            PhysicalSize::new(800, 600),
            (5.0, 552.0),
        )
        .expect("restricted prompt");
        assert_eq!(prompt.kind, HudChatHitTargetKind::Restrictions);
        assert_eq!(prompt.chat_screen_revision, 7);

        let screen = sanitize_hud_chat_restrictions_screen(HudChatRestrictionsScreen {
            generation: 11,
            title: "Restrictions".to_string(),
            reason: HudStyledTextRun::plain("Client settings restriction"),
            permissions: (0..4)
                .map(|index| HudStyledTextRun::plain(format!("permission {index}")))
                .collect(),
            done: "Done".to_string(),
            cursor_position: None,
        })
        .expect("bounded restriction screen");
        assert_eq!(screen.permissions.len(), 4);
        assert!(hud_chat_restrictions_done_contains(
            PhysicalSize::new(800, 600),
            (400.0, 580.0),
        ));
    }
}

/// A HUD sprite uploaded together with its nine-slice scaling, so draw-time geometry can split it
/// into border/edge/center quads instead of stretching a single flat quad.
pub(crate) struct HudNineSliceSprite {
    pub(crate) gpu: HudSpriteGpu,
    pub(crate) scaling: HudNineSliceScaling,
}

pub(crate) struct HudGuiSprite {
    pub(crate) gpu: HudSpriteGpu,
    pub(crate) scaling: HudGuiSpriteScaling,
}

pub(crate) struct HudTooltipStyleSprites {
    pub(crate) background: HudGuiSprite,
    pub(crate) frame: HudGuiSprite,
}

