    pub fn update_hud_item_atlas(&mut self, rgba: &[u8]) -> Result<()> {
        let Some(atlas) = self.hud_item_atlas.as_ref() else {
            return Ok(());
        };
        gpu::update_hud_sprite_gpu(&self.queue, atlas, rgba)
    }

    pub fn update_hud_item_atlas_patches(
        &mut self,
        patches: &[bbb_render_types::AtlasMipPatch],
    ) -> Result<()> {
        let Some(atlas) = self.hud_item_atlas.as_ref() else {
            return Ok(());
        };
        gpu::update_hud_sprite_gpu_patches(&self.queue, atlas, patches)
    }

    pub fn upload_hud_digit_atlas(
        &mut self,
        width: u32,
        height: u32,
        rgba: &[u8],
        glyphs: [HudDigitGlyph; 10],
    ) -> Result<()> {
        self.hud_digit_atlas = Some(self.upload_hud_sprite(width, height, rgba)?);
        self.hud_digit_glyphs = glyphs;
        Ok(())
    }

    pub fn upload_hud_font_atlas(
        &mut self,
        width: u32,
        height: u32,
        rgba: &[u8],
        fonts: impl Into<HudFontGlyphBook>,
    ) -> Result<()> {
        let fonts = fonts.into();
        let glyphs = fonts.glyphs(None).clone();
        self.hud_font_atlas = Some(self.upload_hud_sprite(width, height, rgba)?);
        // Rebuild the advance-grouped obfuscated pool once here, not per frame.
        self.hud_obfuscated_glyph_pool = HudObfuscatedGlyphPool::from_glyph_map(&glyphs);
        self.hud_font_glyphs = glyphs;
        self.hud_font_book = fonts;
        self.rebuild_chat_lines();
        Ok(())
    }

    /// Updates the selected language's paragraph fallback after a font/resource
    /// generation is installed. Logical input measurements remain unchanged;
    /// completed display lines and their cached interaction geometry are rebuilt.
    pub fn set_default_text_right_to_left(&mut self, default_right_to_left: bool) {
        self.hud_font_glyphs
            .set_default_right_to_left(default_right_to_left);
        self.hud_font_book
            .set_default_right_to_left(default_right_to_left);
        self.rebuild_chat_lines();
    }

    pub fn default_text_right_to_left(&self) -> bool {
        self.hud_font_glyphs.default_right_to_left()
    }

