fn push_hud_debug_tinted_rect<'a>(
    vertices: &mut Vec<HudVertex>,
    commands: &mut Vec<HudDrawCommand<'a>>,
    white_pixel: &'a HudSpriteGpu,
    surface_size: PhysicalSize<u32>,
    x: i32,
    y: i32,
    width: u32,
    height: u32,
    tint: [f32; 4],
) {
    if width == 0 || height == 0 {
        return;
    }
    push_hud_draw_with_uv_and_tint(
        vertices,
        commands,
        white_pixel,
        surface_size,
        absolute_hud_rect(x as f32, y as f32, width, height),
        HudUvRect {
            min: [0.0, 0.0],
            max: [1.0, 1.0],
        },
        tint,
    );
}

fn hud_debug_chart_width(surface_size: PhysicalSize<u32>) -> u32 {
    (HUD_DEBUG_CHART_SAMPLE_CAPACITY as u32 + 2).min(surface_size.width / 2)
}

fn hud_debug_chart_visible_samples(samples: &[u64], width: u32) -> &[u64] {
    let sample_start = HUD_DEBUG_CHART_SAMPLE_CAPACITY
        .saturating_sub(usize::try_from(width.saturating_sub(2)).unwrap_or(usize::MAX));
    if sample_start < samples.len() {
        &samples[sample_start..]
    } else {
        &[]
    }
}

fn hud_debug_chart_visible_tps_samples(
    samples: &[HudDebugTpsSample],
    width: u32,
) -> &[HudDebugTpsSample] {
    let sample_start = HUD_DEBUG_CHART_SAMPLE_CAPACITY
        .saturating_sub(usize::try_from(width.saturating_sub(2)).unwrap_or(usize::MAX));
    if sample_start < samples.len() {
        &samples[sample_start..]
    } else {
        &[]
    }
}

fn hud_debug_fps_chart_display_string(nanos: f64) -> String {
    format!("{} ms", hud_debug_fps_chart_millis(nanos).round() as i64)
}

fn hud_debug_fps_chart_sample_height(nanos: u64) -> i32 {
    hud_debug_fps_chart_sample_height_f64(nanos as f64)
}

fn hud_debug_fps_chart_sample_height_f64(nanos: f64) -> i32 {
    (hud_debug_fps_chart_millis(nanos) * HUD_DEBUG_CHART_HEIGHT as f64
        / HUD_DEBUG_FPS_CHART_TOP_VALUE_MS)
        .round()
        .clamp(0.0, i32::MAX as f64) as i32
}

fn hud_debug_fps_configured_framerate_height(framerate_limit: u32) -> i32 {
    hud_debug_fps_chart_sample_height_f64(1.0E9 / f64::from(framerate_limit))
}

fn hud_debug_fps_chart_sample_tint(nanos: u64) -> [f32; 4] {
    let millis = hud_debug_fps_chart_millis(nanos as f64);
    hud_argb_to_tint(hud_debug_chart_sample_argb(
        millis, 0.0, 0xFF00FF00, 28.0, 0xFFFFFF00, 56.0, 0xFFFF0000,
    ))
}

fn hud_debug_fps_chart_millis(nanos: f64) -> f64 {
    nanos / 1_000_000.0
}

fn hud_debug_tps_chart_display_string(nanos: f64) -> String {
    format!("{} ms", hud_debug_fps_chart_millis(nanos).round() as i64)
}

fn hud_debug_tps_chart_sample_height(nanos: u64, milliseconds_per_tick: f32) -> i32 {
    let mspt = f64::from(milliseconds_per_tick.max(f32::EPSILON));
    (hud_debug_fps_chart_millis(nanos as f64) * HUD_DEBUG_CHART_HEIGHT as f64 / mspt)
        .round()
        .clamp(0.0, i32::MAX as f64) as i32
}

fn hud_debug_tps_chart_sample_tint(nanos: u64, milliseconds_per_tick: f32) -> [f32; 4] {
    let mspt = f64::from(milliseconds_per_tick.max(f32::EPSILON));
    let millis = hud_debug_fps_chart_millis(nanos as f64);
    hud_argb_to_tint(hud_debug_chart_sample_argb(
        millis,
        mspt,
        0xFF00FF00,
        mspt * 1.125,
        0xFFFFFF00,
        mspt * 1.25,
        0xFFFF0000,
    ))
}

fn hud_debug_tps_chart_tps_label(milliseconds_per_tick: f32) -> String {
    format!(
        "{:.1} TPS",
        1000.0 / milliseconds_per_tick.max(f32::EPSILON)
    )
}

fn hud_debug_tps_chart_aggregation_nanos(sample: HudDebugTpsSample) -> u64 {
    sample.full_tick_nanos.saturating_sub(sample.idle_nanos)
}

fn hud_debug_tps_chart_other_nanos(sample: HudDebugTpsSample) -> u64 {
    sample
        .full_tick_nanos
        .saturating_sub(sample.idle_nanos)
        .saturating_sub(sample.tick_server_method_nanos)
        .saturating_sub(sample.scheduled_tasks_nanos)
}

fn hud_debug_ping_chart_display_string(millis: f64) -> String {
    format!("{} ms", millis.round() as i64)
}

fn hud_debug_ping_chart_sample_height(millis: u64) -> i32 {
    (millis as f64 * HUD_DEBUG_CHART_HEIGHT as f64 / 500.0)
        .round()
        .clamp(0.0, i32::MAX as f64) as i32
}

fn hud_debug_ping_chart_sample_tint(millis: u64) -> [f32; 4] {
    hud_argb_to_tint(hud_debug_chart_sample_argb(
        millis as f64,
        0.0,
        0xFF00FF00,
        250.0,
        0xFFFFFF00,
        500.0,
        0xFFFF0000,
    ))
}

fn hud_debug_bandwidth_chart_display_string(bytes_per_tick: f64) -> String {
    hud_debug_bandwidth_chart_display_string_internal(bytes_per_tick * 20.0)
}

fn hud_debug_bandwidth_chart_display_string_internal(bytes_per_second: f64) -> String {
    if bytes_per_second >= 1_048_576.0 {
        format!("{:.1} MiB/s", bytes_per_second / 1_048_576.0)
    } else if bytes_per_second >= 1_024.0 {
        format!("{:.1} KiB/s", bytes_per_second / 1_024.0)
    } else {
        format!("{} B/s", bytes_per_second.floor() as u64)
    }
}

fn hud_debug_bandwidth_chart_sample_height(bytes_per_tick: u64) -> i32 {
    hud_debug_bandwidth_chart_sample_height_internal(bytes_per_tick as f64 * 20.0)
}

fn hud_debug_bandwidth_chart_sample_height_internal(bytes_per_second: f64) -> i32 {
    ((bytes_per_second + 1.0).ln() * HUD_DEBUG_CHART_HEIGHT as f64 / 1_048_576.0_f64.ln())
        .round()
        .clamp(0.0, i32::MAX as f64) as i32
}

fn hud_debug_bandwidth_chart_sample_tint(bytes_per_tick: u64) -> [f32; 4] {
    hud_argb_to_tint(hud_debug_chart_sample_argb(
        bytes_per_tick as f64 * 20.0,
        0.0,
        0xFF00FFFF,
        8_192.0,
        0xFFA0A0FF,
        10_485_760.0,
        0xFFFF0000,
    ))
}

fn hud_debug_chart_sample_argb(
    sample: f64,
    min: f64,
    min_color: u32,
    mid: f64,
    mid_color: u32,
    max: f64,
    max_color: u32,
) -> u32 {
    let sample = sample.clamp(min, max);
    if sample < mid {
        hud_argb_lerp((sample - min) / (mid - min), min_color, mid_color)
    } else {
        hud_argb_lerp((sample - mid) / (max - mid), mid_color, max_color)
    }
}

fn hud_argb_lerp(alpha: f64, start: u32, end: u32) -> u32 {
    let alpha = alpha.clamp(0.0, 1.0);
    let a = hud_lerp_channel(alpha, (start >> 24) & 0xFF, (end >> 24) & 0xFF);
    let r = hud_lerp_channel(alpha, (start >> 16) & 0xFF, (end >> 16) & 0xFF);
    let g = hud_lerp_channel(alpha, (start >> 8) & 0xFF, (end >> 8) & 0xFF);
    let b = hud_lerp_channel(alpha, start & 0xFF, end & 0xFF);
    (a << 24) | (r << 16) | (g << 8) | b
}

fn hud_lerp_channel(alpha: f64, start: u32, end: u32) -> u32 {
    let value = start as i32 + (alpha * f64::from(end as i32 - start as i32)).floor() as i32;
    value.clamp(0, 255) as u32
}

fn hud_argb_multiply(lhs: u32, rhs: u32) -> u32 {
    if lhs == 0xFFFF_FFFF {
        return rhs;
    }
    if rhs == 0xFFFF_FFFF {
        return lhs;
    }
    let a = ((lhs >> 24) & 0xFF) * ((rhs >> 24) & 0xFF) / 255;
    let r = ((lhs >> 16) & 0xFF) * ((rhs >> 16) & 0xFF) / 255;
    let g = ((lhs >> 8) & 0xFF) * ((rhs >> 8) & 0xFF) / 255;
    let b = (lhs & 0xFF) * (rhs & 0xFF) / 255;
    (a << 24) | (r << 16) | (g << 8) | b
}

fn hud_argb_to_tint(argb: u32) -> [f32; 4] {
    [
        ((argb >> 16) & 0xFF) as f32 / 255.0,
        ((argb >> 8) & 0xFF) as f32 / 255.0,
        (argb & 0xFF) as f32 / 255.0,
        ((argb >> 24) & 0xFF) as f32 / 255.0,
    ]
}

fn hud_debug_overlay_line_origin(
    surface_size: PhysicalSize<u32>,
    width: u32,
    line_index: usize,
    align_left: bool,
) -> (i32, i32) {
    let left = if align_left {
        HUD_DEBUG_OVERLAY_MARGIN_X
    } else {
        i32::try_from(surface_size.width)
            .unwrap_or(i32::MAX)
            .saturating_sub(HUD_DEBUG_OVERLAY_MARGIN_X)
            .saturating_sub(i32::try_from(width).unwrap_or(i32::MAX))
    };
    let top = HUD_DEBUG_OVERLAY_MARGIN_Y.saturating_add(
        i32::try_from(line_index)
            .unwrap_or(i32::MAX)
            .saturating_mul(HUD_DEBUG_OVERLAY_LINE_HEIGHT),
    );
    (left, top)
}

fn hud_debug_lightmap_preview_rect(surface_size: PhysicalSize<u32>) -> HudRect {
    let (x, y) = hud_debug_lightmap_preview_origin(surface_size);
    absolute_hud_rect(
        x as f32,
        y as f32,
        HUD_DEBUG_LIGHTMAP_PREVIEW_SIZE,
        HUD_DEBUG_LIGHTMAP_PREVIEW_SIZE,
    )
}

fn hud_debug_lightmap_preview_border_rect(surface_size: PhysicalSize<u32>) -> HudRect {
    let (x, y) = hud_debug_lightmap_preview_origin(surface_size);
    absolute_hud_rect(
        (x - HUD_DEBUG_LIGHTMAP_PREVIEW_BORDER) as f32,
        (y - HUD_DEBUG_LIGHTMAP_PREVIEW_BORDER) as f32,
        HUD_DEBUG_LIGHTMAP_PREVIEW_SIZE + (HUD_DEBUG_LIGHTMAP_PREVIEW_BORDER as u32 * 2),
        HUD_DEBUG_LIGHTMAP_PREVIEW_SIZE + (HUD_DEBUG_LIGHTMAP_PREVIEW_BORDER as u32 * 2),
    )
}

fn hud_debug_lightmap_preview_origin(surface_size: PhysicalSize<u32>) -> (i32, i32) {
    let x = i32::try_from(surface_size.width)
        .unwrap_or(i32::MAX)
        .saturating_sub(HUD_DEBUG_LIGHTMAP_PREVIEW_SIZE as i32)
        .saturating_sub(HUD_DEBUG_LIGHTMAP_PREVIEW_MARGIN);
    let y = i32::try_from(surface_size.height)
        .unwrap_or(i32::MAX)
        .saturating_sub(HUD_DEBUG_LIGHTMAP_PREVIEW_SIZE as i32)
        .saturating_sub(HUD_DEBUG_LIGHTMAP_PREVIEW_MARGIN);
    (x, y)
}

fn hud_debug_lightmap_preview_uv() -> HudUvRect {
    HudUvRect {
        min: [0.0, 1.0],
        max: [1.0, 0.0],
    }
}

/// Resolved main-pass colour of a styled run: the run's `Style` colour over
/// the line's base tint (vanilla `StringRenderOutput.getTextColor`), keeping
/// the base alpha.
fn hud_run_color_tint(run: &HudStyledTextRun, base_tint: [f32; 4]) -> [f32; 4] {
    match run.color {
        Some(rgb) => [
            ((rgb >> 16) & 0xFF) as f32 / 255.0,
            ((rgb >> 8) & 0xFF) as f32 / 255.0,
            (rgb & 0xFF) as f32 / 255.0,
            base_tint[3],
        ],
        None => base_tint,
    }
}

/// Vanilla `StringRenderOutput.getShadowColor` default branch:
/// `ARGB.scaleRGB(textColor, 0.25)` — the drop shadow is the text colour at a
/// quarter brightness (alpha kept).
fn hud_text_shadow_tint(tint: [f32; 4]) -> [f32; 4] {
    [tint[0] * 0.25, tint[1] * 0.25, tint[2] * 0.25, tint[3]]
}

/// One draw pass (shadow or main) of a styled text line: glyph quads in draw
/// order followed by underline/strikethrough bars, mirroring vanilla
/// `Font.StringRenderOutput.visit` (glyphs first, effects after). All
/// geometry is produced by the locked `styled_quads` / `styled_effect_rects`
/// mechanisms; tints are resolved per run (shadow passes scale the run
/// colour, vanilla `getShadowColor`).
#[derive(Debug, Clone, PartialEq)]
struct HudStyledTextPassGeometry {
    glyph_quads: Vec<(HudGlyphQuad, [f32; 4])>,
    effect_rects: Vec<(HudEffectRect, [f32; 4])>,
}

#[derive(Debug, Clone, Copy, PartialEq)]
struct HudResolvedTextRun<'a> {
    visual: &'a HudStyledTextRun,
    glyphs: &'a HudFontGlyphMap,
    obfuscated_pool: &'a HudObfuscatedGlyphPool,
}

/// Computes one pass of a styled line at `origin` (line top-left in HUD
/// pixels). Each resolved run supplies its selected font glyphs and matching
/// obfuscation pool; plain HUD text maps every run to the default font while
/// trusted-Component surfaces may switch fonts without forking the geometry
/// walk. `width_limit` reproduces the label budget semantics: the walk stops
/// once the pen reaches the limit and a glyph/effect is only emitted when its
/// cell/advance still fits (the limit is in font pixels, pre-scale).
///
/// `scale` mirrors a vanilla pose scale around `origin`
/// (`PoseStack.scale` before the draw, as `Gui.extractTitle` does for the
/// 4x title / 2x subtitle): every font-pixel offset — pen, glyph cells,
/// shadow offset, bold offset and effect bars — is multiplied uniformly.
/// `1.0` reproduces the unscaled label path.
///
/// Italic runs are sheared through the locked `styled_quads` primitive (top
/// edge `1-0.25*up`, bottom `1-0.25*down`). Obfuscated (`§k`) non-space glyphs
/// draw a random equal-advance substitute (`FontSet.getRandomGlyph`) picked
/// from that run's selected pool; `obfuscated_seed` (the render frame counter)
/// seeds one deterministic per-pass LCG so the jitter is reproducible across
/// font changes and the shadow pass picks the same substitutes as the main
/// pass. Like `Font.getGlyph` followed by `PreparedTextBuilder.accept`, pen,
/// effect and offset metrics come from the selected baked glyph; the random
/// pool is bucketed by the original glyph's rounded plain advance.
#[allow(clippy::too_many_arguments)]
fn hud_styled_text_pass_geometry(
    runs: &[HudStyledTextRun],
    glyphs: &HudFontGlyphMap,
    obfuscated_pool: &HudObfuscatedGlyphPool,
    obfuscated_seed: u64,
    origin: (f32, f32),
    shadow_offset: f32,
    is_shadow: bool,
    base_tint: [f32; 4],
    width_limit: Option<u32>,
    scale: f32,
) -> HudStyledTextPassGeometry {
    hud_resolved_text_pass_geometry(
        runs.iter().map(|visual| HudResolvedTextRun {
            visual,
            glyphs,
            obfuscated_pool,
        }),
        true,
        glyphs.default_right_to_left(),
        obfuscated_seed,
        origin,
        shadow_offset,
        is_shadow,
        base_tint,
        width_limit,
        scale,
    )
}

#[allow(clippy::too_many_arguments)]
fn hud_logical_styled_text_pass_geometry(
    runs: &[HudStyledTextRun],
    glyphs: &HudFontGlyphMap,
    obfuscated_pool: &HudObfuscatedGlyphPool,
    obfuscated_seed: u64,
    origin: (f32, f32),
    shadow_offset: f32,
    is_shadow: bool,
    base_tint: [f32; 4],
    width_limit: Option<u32>,
    scale: f32,
) -> HudStyledTextPassGeometry {
    // Vanilla's one-line EditBox explicitly supplies
    // `FormattedCharSequence.forward`, so its visible slice must stay aligned
    // with logical cursor and selection offsets even in an RTL language.
    hud_resolved_text_pass_geometry(
        runs.iter().map(|visual| HudResolvedTextRun {
            visual,
            glyphs,
            obfuscated_pool,
        }),
        false,
        glyphs.default_right_to_left(),
        obfuscated_seed,
        origin,
        shadow_offset,
        is_shadow,
        base_tint,
        width_limit,
        scale,
    )
}

#[allow(clippy::too_many_arguments)]
fn hud_component_text_pass_geometry(
    runs: &[HudComponentTextRun],
    fonts: &HudFontGlyphBook,
    obfuscated_seed: u64,
    origin: (f32, f32),
    shadow_offset: f32,
    is_shadow: bool,
    base_tint: [f32; 4],
    width_limit: Option<u32>,
    scale: f32,
) -> HudStyledTextPassGeometry {
    hud_resolved_text_pass_geometry(
        runs.iter().map(|run| HudResolvedTextRun {
            visual: &run.visual,
            glyphs: fonts.glyphs(run.font.as_deref()),
            obfuscated_pool: fonts.obfuscated_pool(run.font.as_deref()),
        }),
        true,
        fonts.default_right_to_left(),
        obfuscated_seed,
        origin,
        shadow_offset,
        is_shadow,
        base_tint,
        width_limit,
        scale,
    )
}

#[allow(clippy::too_many_arguments)]
fn hud_resolved_text_pass_geometry<'a>(
    runs: impl IntoIterator<Item = HudResolvedTextRun<'a>>,
    apply_visual_order: bool,
    default_right_to_left: bool,
    obfuscated_seed: u64,
    origin: (f32, f32),
    shadow_offset: f32,
    is_shadow: bool,
    base_tint: [f32; 4],
    width_limit: Option<u32>,
    scale: f32,
) -> HudStyledTextPassGeometry {
    let mut geometry = HudStyledTextPassGeometry {
        glyph_quads: Vec::new(),
        effect_rects: Vec::new(),
    };
    let mut pen_x = 0.0_f32;
    let mut first_in_line = true;
    // One LCG per pass, reset from the frame seed so the shadow and main passes
    // choose identical substitutes (the shadow is the main glyph at +1,+1); it
    // advances only when an obfuscated glyph is actually substituted, matching
    // vanilla `Font.random` (touched once per `getRandomGlyph`).
    let mut obfuscated_random = HudObfuscatedRandom::with_seed(obfuscated_seed);
    let logical = runs
        .into_iter()
        .flat_map(|resolved| resolved.visual.text.chars().map(move |ch| (ch, resolved)))
        .collect::<Vec<_>>();
    let ordered = if apply_visual_order {
        visual_order(&logical, default_right_to_left)
    } else {
        logical
    };
    'runs: for (ch, resolved) in ordered {
        let run = resolved.visual;
        let run_tint = hud_run_color_tint(run, base_tint);
        let tint = if is_shadow {
            hud_text_shadow_tint(run_tint)
        } else {
            run_tint
        };
        if width_limit.is_some_and(|limit| pen_x >= limit as f32) {
            break 'runs;
        }
        let base_glyph = hud_font_glyph(ch, resolved.glyphs);
        // Vanilla `Font.getGlyph`: obfuscated non-space codepoints draw a
        // random equal-advance glyph; everything else draws its own glyph.
        let glyph = if run.style.obfuscated && ch != ' ' {
            resolved
                .obfuscated_pool
                .random_glyph(base_glyph.advance, &mut obfuscated_random)
                .unwrap_or(base_glyph)
        } else {
            base_glyph
        };
        // `Font.StringRenderOutput.accept` reads metrics from the selected
        // baked glyph. Obfuscation buckets share the plain integer advance,
        // but a unihex substitute can still carry its provider-specific
        // half-pixel bold/shadow offsets.
        let advance = glyph.styled_advance_f32(run.style);
        // Glyph geometry is produced in font pixels relative to `origin`
        // and mapped through `origin + scale * offset`, exactly a vanilla
        // pose scale (the shadow offset scales with the pose too).
        let glyph_shadow_offset = shadow_offset * glyph.shadow_offset;
        let x = pen_x + glyph_shadow_offset;
        let y = glyph_shadow_offset;
        if glyph.width > 0
            && glyph.height > 0
            && width_limit.is_none_or(|limit| pen_x + glyph.rendered_width() <= limit as f32)
        {
            for quad in glyph.styled_quads(x, y, run.style, false) {
                let quad = HudGlyphQuad {
                    corners: quad
                        .corners
                        .map(|[cx, cy]| [origin.0 + cx * scale, origin.1 + cy * scale]),
                    ..quad
                };
                geometry.glyph_quads.push((quad, tint));
            }
        }
        // Underline/strikethrough bars follow the advance, unaffected by the
        // obfuscated bitmap swap, so they read the original glyph.
        if width_limit.is_none_or(|limit| pen_x + advance <= limit as f32) {
            for rect in glyph.styled_effect_rects(x, y, run.style, first_in_line) {
                let rect = HudEffectRect {
                    x0: origin.0 + rect.x0 * scale,
                    y0: origin.1 + rect.y0 * scale,
                    x1: origin.0 + rect.x1 * scale,
                    y1: origin.1 + rect.y1 * scale,
                    ..rect
                };
                geometry.effect_rects.push((rect, tint));
            }
        }
        pen_x += advance;
        first_in_line = false;
    }
    geometry
}

fn push_hud_styled_text_pass<'a>(
    vertices: &mut Vec<HudVertex>,
    commands: &mut Vec<HudDrawCommand<'a>>,
    white_pixel: &'a HudSpriteGpu,
    font_atlas: &'a HudSpriteGpu,
    surface_size: PhysicalSize<u32>,
    geometry: &HudStyledTextPassGeometry,
) {
    for (quad, tint) in &geometry.glyph_quads {
        let start = vertices.len() as u32;
        vertices.extend_from_slice(&hud_styled_quad_vertices(
            surface_size,
            quad.corners,
            quad.uv,
            *tint,
        ));
        let end = vertices.len() as u32;
        push_hud_sprite_batch(commands, font_atlas, start, end);
    }
    for (rect, tint) in &geometry.effect_rects {
        let start = vertices.len() as u32;
        vertices.extend_from_slice(&hud_styled_quad_vertices(
            surface_size,
            [
                [rect.x0, rect.y0],
                [rect.x0, rect.y1],
                [rect.x1, rect.y1],
                [rect.x1, rect.y0],
            ],
            HudUvRect {
                min: [0.0, 0.0],
                max: [1.0, 1.0],
            },
            *tint,
        ));
        let end = vertices.len() as u32;
        push_hud_sprite_batch(commands, white_pixel, start, end);
    }
}

/// Extends the current GUI mesh when consecutive vertices use the same
/// texture. Vanilla 26.1's `GuiRenderer.addElementToMesh` keeps one
/// `BufferBuilder` until scissor, pipeline, or `TextureSetup` changes; glyphs
/// from the same font atlas therefore form one draw rather than one draw per
/// quad. A non-sprite command or texture transition remains an ordering
/// boundary.
fn push_hud_sprite_batch<'a>(
    commands: &mut Vec<HudDrawCommand<'a>>,
    sprite: &'a HudSpriteGpu,
    start: u32,
    end: u32,
) {
    if let Some(HudDrawCommand::Sprite {
        sprite: previous_sprite,
        end: previous_end,
        ..
    }) = commands.last_mut()
    {
        if std::ptr::eq(*previous_sprite, sprite) && *previous_end == start {
            *previous_end = end;
            return;
        }
    }
    commands.push(HudDrawCommand::Sprite { sprite, start, end });
}

#[allow(clippy::too_many_arguments)]
fn push_hud_inventory_tooltip<'a>(
    vertices: &mut Vec<HudVertex>,
    commands: &mut Vec<HudDrawCommand<'a>>,
    white_pixel: &'a HudSpriteGpu,
    tooltip_background: Option<&'a HudNineSliceSprite>,
    tooltip_frame: Option<&'a HudNineSliceSprite>,
    tooltip_styles: &'a HashMap<String, HudTooltipStyleSprites>,
    font_atlas: Option<&'a HudSpriteGpu>,
    fonts: &HudFontGlyphBook,
    obfuscated_seed: u64,
    surface_size: PhysicalSize<u32>,
    screen: &HudInventoryScreen,
) {
    let (Some(font_atlas), Some(tooltip)) = (font_atlas, screen.tooltip.as_ref()) else {
        return;
    };
    let Some(text_height) = hud_inventory_tooltip_text_height(tooltip.lines.len()) else {
        return;
    };
    let Some(text_width) = tooltip
        .lines
        .iter()
        .filter_map(|line| hud_component_runs_width(&line.runs, fonts))
        .max()
    else {
        return;
    };

    let background_rect = hud_inventory_tooltip_background_hud_rect(
        surface_size,
        screen.width,
        screen.height,
        tooltip.x,
        tooltip.y,
        text_width,
        text_height,
    );
    if let Some(style) = tooltip.style.as_deref() {
        if let Some(sprites) = tooltip_styles.get(style) {
            push_hud_gui_sprite(
                vertices,
                commands,
                &sprites.background,
                surface_size,
                background_rect,
            );
            push_hud_gui_sprite(
                vertices,
                commands,
                &sprites.frame,
                surface_size,
                background_rect,
            );
        } else {
            push_hud_inventory_tooltip_flat_background(
                vertices,
                commands,
                white_pixel,
                surface_size,
                background_rect,
            );
        }
    } else if let (Some(background), Some(frame)) = (tooltip_background, tooltip_frame) {
        // Vanilla `TooltipRenderUtil.extractTooltipBackground`: default nine-slice
        // `tooltip/background` then `tooltip/frame` over the same padded rect.
        for segment in hud_inventory_tooltip_sprite_segments(
            background_rect,
            background.scaling,
            frame.scaling,
        ) {
            let sprite = match segment.layer {
                HudTooltipSpriteLayer::Background => &background.gpu,
                HudTooltipSpriteLayer::Frame => &frame.gpu,
            };
            push_hud_draw_with_uv_and_tint(
                vertices,
                commands,
                sprite,
                surface_size,
                segment.rect,
                segment.uv,
                HUD_TINT_WHITE,
            );
        }
    } else {
        // Missing-asset fallback: the legacy flat translucent background quad.
        push_hud_inventory_tooltip_flat_background(
            vertices,
            commands,
            white_pixel,
            surface_size,
            background_rect,
        );
    }

    // Vanilla pass order kept from the plain path: every line's shadow first,
    // then every line's main colour; per-run tints resolve inside each pass.
    for (shadow_offset, is_shadow) in [(1.0, true), (0.0, false)] {
        for (line_index, line) in tooltip.lines.iter().enumerate() {
            let origin = hud_inventory_tooltip_line_origin(
                surface_size,
                screen.width,
                screen.height,
                tooltip.x,
                tooltip.y,
                text_width,
                text_height,
                line_index,
            );
            let geometry = hud_component_text_pass_geometry(
                &line.runs,
                fonts,
                obfuscated_seed,
                origin,
                shadow_offset,
                is_shadow,
                line.tint,
                None,
                1.0,
            );
            push_hud_styled_text_pass(
                vertices,
                commands,
                white_pixel,
                font_atlas,
                surface_size,
                &geometry,
            );
        }
    }
}

fn push_hud_gui_sprite<'a>(
    vertices: &mut Vec<HudVertex>,
    commands: &mut Vec<HudDrawCommand<'a>>,
    sprite: &'a HudGuiSprite,
    surface_size: PhysicalSize<u32>,
    target: HudRect,
) {
    match sprite.scaling {
        HudGuiSpriteScaling::Stretch => push_hud_draw_with_uv_and_tint(
            vertices,
            commands,
            &sprite.gpu,
            surface_size,
            target,
            HudUvRect {
                min: [0.0, 0.0],
                max: [1.0, 1.0],
            },
            HUD_TINT_WHITE,
        ),
        HudGuiSpriteScaling::Tile { width, height } => {
            for segment in tiled_sprite_segments(target, width, height) {
                push_hud_draw_with_uv_and_tint(
                    vertices,
                    commands,
                    &sprite.gpu,
                    surface_size,
                    segment.rect,
                    segment.uv,
                    HUD_TINT_WHITE,
                );
            }
        }
        HudGuiSpriteScaling::NineSlice(scaling) => {
            for segment in nine_slice_segments(target, scaling) {
                push_hud_draw_with_uv_and_tint(
                    vertices,
                    commands,
                    &sprite.gpu,
                    surface_size,
                    segment.rect,
                    segment.uv,
                    HUD_TINT_WHITE,
                );
            }
        }
    }
}

fn push_hud_inventory_tooltip_flat_background<'a>(
    vertices: &mut Vec<HudVertex>,
    commands: &mut Vec<HudDrawCommand<'a>>,
    white_pixel: &'a HudSpriteGpu,
    surface_size: PhysicalSize<u32>,
    target: HudRect,
) {
    push_hud_draw_with_uv_and_tint(
        vertices,
        commands,
        white_pixel,
        surface_size,
        target,
        HudUvRect {
            min: [0.0, 0.0],
            max: [1.0, 1.0],
        },
        HUD_TOOLTIP_BACKGROUND_TINT,
    );
}

fn hud_digit_text_width(text: &str, glyphs: &[HudDigitGlyph; 10]) -> Option<u32> {
    let mut width = 0u32;
    for digit in text.bytes() {
        if !digit.is_ascii_digit() {
            return None;
        }
        width = width.checked_add(glyphs[(digit - b'0') as usize].advance)?;
    }
    (width > 0).then_some(width)
}

/// Test-only single-style wrappers over [`hud_font_runs_width`], the one
/// width implementation.
#[cfg(test)]
fn hud_font_text_width(text: &str, glyphs: &HudFontGlyphMap) -> Option<u32> {
    hud_font_text_width_styled(text, glyphs, HudTextStyle::default())
}

#[cfg(test)]
fn hud_font_text_width_styled(
    text: &str,
    glyphs: &HudFontGlyphMap,
    style: HudTextStyle,
) -> Option<u32> {
    hud_font_runs_width(
        &[HudStyledTextRun {
            text: text.to_string(),
            style,
            color: None,
        }],
        glyphs,
    )
}

/// Vanilla `Font.plainSubstrByWidth` cursor equivalent for a plain search
/// field: include glyphs while the cumulative unstyled advance fits inside
/// the caller's pixel budget.
fn hud_plain_text_cursor_for_width(
    text: &str,
    width: u32,
    glyphs: &HudFontGlyphMap,
) -> Option<usize> {
    hud_plain_text_cursor_for_width_from(text, 0, width, glyphs)
}

fn hud_plain_text_cursor_for_width_from(
    text: &str,
    display_start: usize,
    width: u32,
    glyphs: &HudFontGlyphMap,
) -> Option<usize> {
    if glyphs.len() == 0 {
        return None;
    }
    let text_len = text.chars().count();
    let display_start = display_start.min(text_len);
    let display_len = hud_plain_head_char_len_by_width(
        text,
        display_start,
        text_len.saturating_sub(display_start),
        width,
        glyphs,
    );
    Some(display_start.saturating_add(display_len))
}

fn hud_plain_text_display_start_for_width(
    text: &str,
    scroll_to: usize,
    width: u32,
    glyphs: &HudFontGlyphMap,
) -> Option<usize> {
    (glyphs.len() > 0).then(|| hud_text_input_display_start(text, scroll_to, width, glyphs))
}

/// Measures a completed formatted line after vanilla language visual ordering.
/// Each visual glyph contributes `GlyphInfo.getAdvance(style.isBold())`; this
/// includes Arabic shaping compaction such as Lam-Alef.
fn hud_font_runs_width(runs: &[HudStyledTextRun], glyphs: &HudFontGlyphMap) -> Option<u32> {
    let logical = runs
        .iter()
        .flat_map(|run| run.text.chars().map(move |ch| (ch, run)))
        .collect::<Vec<_>>();
    let mut width = 0.0_f32;
    for (ch, run) in visual_order(&logical, glyphs.default_right_to_left()) {
        width += hud_font_glyph(ch, glyphs).styled_advance_f32(run.style);
    }
    (width > 0.0).then_some(width.ceil() as u32)
}

/// Measures the unshaped logical buffer used by wrapping, editing cursors, and
/// selections. Vanilla `Font.width(String)` does not apply language ordering.
fn hud_logical_font_runs_width(runs: &[HudStyledTextRun], glyphs: &HudFontGlyphMap) -> Option<u32> {
    let mut width = 0.0_f32;
    for run in runs {
        for ch in run.text.chars() {
            width += hud_font_glyph(ch, glyphs).styled_advance_f32(run.style);
        }
    }
    (width > 0.0).then_some(width.ceil() as u32)
}

fn hud_component_runs_width(runs: &[HudComponentTextRun], fonts: &HudFontGlyphBook) -> Option<u32> {
    let logical = runs
        .iter()
        .flat_map(|run| run.visual.text.chars().map(move |ch| (ch, run)))
        .collect::<Vec<_>>();
    let mut width = 0.0_f32;
    for (ch, run) in visual_order(&logical, fonts.default_right_to_left()) {
        let glyphs = fonts.glyphs(run.font.as_deref());
        width += hud_font_glyph(ch, glyphs).styled_advance_f32(run.visual.style);
    }
    (width > 0.0).then_some(width.ceil() as u32)
}

const HUD_CHAT_MAX_WIDTH: u32 = 320;
const HUD_CHAT_MAX_WRAPPED_LINES: usize = 100;
const HUD_CHAT_MODIFIED_ICON_WIDTH_WITH_GAP: u32 = 15;

#[derive(Debug, Clone, PartialEq, Eq)]
struct HudChatStyledChar {
    ch: char,
    style: HudTextStyle,
    color: Option<u32>,
    font: Option<String>,
    target_index: Option<u16>,
}

fn hud_wrap_chat_messages(
    messages: &[HudChatMessage],
    fonts: &HudFontGlyphBook,
) -> Vec<HudChatLine> {
    let mut lines = Vec::with_capacity(messages.len().min(HUD_CHAT_MAX_WRAPPED_LINES));
    for message in messages {
        let width = HUD_CHAT_MAX_WIDTH.saturating_sub(
            (message
                .tag
                .as_ref()
                .is_some_and(|tag| tag.kind == HudChatTagKind::Modified))
            .then_some(HUD_CHAT_MODIFIED_ICON_WIDTH_WITH_GAP)
            .unwrap_or(0),
        );
        let wrapped = hud_wrap_component_runs_with_interactions(
            &message.runs,
            &message.interactions,
            width.max(1),
            fonts,
        );
        let wrapped_len = wrapped.len();
        for (index, wrapped) in wrapped.into_iter().enumerate() {
            lines.push(HudChatLine {
                display_sequence: message.display_sequence,
                added_tick: message.added_tick,
                runs: wrapped.runs,
                tag: message.tag.clone(),
                interactions: wrapped.interactions,
                end_of_entry: index + 1 == wrapped_len,
            });
        }
    }
    if lines.len() > HUD_CHAT_MAX_WRAPPED_LINES {
        let excess = lines.len() - HUD_CHAT_MAX_WRAPPED_LINES;
        lines.drain(..excess);
    }
    lines
}

fn hud_wrap_chat_runs(
    runs: &[HudStyledTextRun],
    max_width: u32,
    glyphs: &HudFontGlyphMap,
) -> Vec<Vec<HudStyledTextRun>> {
    hud_wrap_chat_runs_with_interactions(runs, &[], max_width, glyphs)
        .into_iter()
        .map(|line| line.runs)
        .collect()
}

#[derive(Debug, Clone, PartialEq)]
struct HudWrappedChatLine {
    runs: Vec<HudStyledTextRun>,
    interactions: Vec<HudChatLineInteraction>,
}

#[derive(Debug, Clone, PartialEq)]
struct HudWrappedComponentChatLine {
    runs: Vec<HudComponentTextRun>,
    interactions: Vec<HudChatLineInteraction>,
}

fn hud_wrap_chat_runs_with_interactions(
    runs: &[HudStyledTextRun],
    interactions: &[HudChatInteraction],
    max_width: u32,
    glyphs: &HudFontGlyphMap,
) -> Vec<HudWrappedChatLine> {
    let runs = runs
        .iter()
        .cloned()
        .map(|visual| HudComponentTextRun { visual, font: None })
        .collect::<Vec<_>>();
    hud_wrap_component_runs(
        &runs,
        interactions,
        max_width,
        HudChatFontResolver::Default(glyphs),
    )
    .into_iter()
    .map(|line| HudWrappedChatLine {
        runs: line.runs.into_iter().map(|run| run.visual).collect(),
        interactions: line.interactions,
    })
    .collect()
}

fn hud_wrap_component_runs_with_interactions(
    runs: &[HudComponentTextRun],
    interactions: &[HudChatInteraction],
    max_width: u32,
    fonts: &HudFontGlyphBook,
) -> Vec<HudWrappedComponentChatLine> {
    hud_wrap_component_runs(
        runs,
        interactions,
        max_width,
        HudChatFontResolver::Book(fonts),
    )
}

#[derive(Debug, Clone, Copy)]
enum HudChatFontResolver<'a> {
    Default(&'a HudFontGlyphMap),
    Book(&'a HudFontGlyphBook),
}

impl<'a> HudChatFontResolver<'a> {
    fn glyphs(self, font: Option<&str>) -> &'a HudFontGlyphMap {
        match self {
            Self::Default(glyphs) => glyphs,
            Self::Book(fonts) => fonts.glyphs(font),
        }
    }

    fn default_right_to_left(self) -> bool {
        match self {
            Self::Default(glyphs) => glyphs.default_right_to_left(),
            Self::Book(fonts) => fonts.default_right_to_left(),
        }
    }
}

fn hud_wrap_component_runs(
    runs: &[HudComponentTextRun],
    interactions: &[HudChatInteraction],
    max_width: u32,
    fonts: HudChatFontResolver<'_>,
) -> Vec<HudWrappedComponentChatLine> {
    let mut char_index = 0usize;
    let chars = runs
        .iter()
        .flat_map(|run| {
            run.visual
                .text
                .chars()
                .map(move |ch| (ch, run.visual.style, run.visual.color, run.font.clone()))
        })
        .map(|(ch, style, color, font)| {
            let target_index = interactions
                .iter()
                .find(|interaction| {
                    interaction.start_char <= char_index && char_index < interaction.end_char
                })
                .map(|interaction| interaction.target_index);
            char_index = char_index.saturating_add(1);
            HudChatStyledChar {
                ch,
                style,
                color,
                font,
                target_index,
            }
        })
        .collect::<Vec<_>>();
    let mut result = Vec::new();
    let mut line = Vec::<HudChatStyledChar>::new();
    let mut width = 0.0_f32;
    let mut last_break = None;

    for styled in chars {
        if styled.ch == '\n' {
            trim_chat_line_end(&mut line);
            result.push(hud_chat_chars_to_component_line(&line, interactions, fonts));
            line.clear();
            width = 0.0;
            last_break = None;
            continue;
        }
        let advance = hud_font_glyph(styled.ch, fonts.glyphs(styled.font.as_deref()))
            .styled_advance_f32(styled.style);
        if !line.is_empty() && width + advance > max_width as f32 {
            if let Some(break_index) = last_break {
                let mut carry = line.split_off(break_index);
                trim_chat_line_end(&mut line);
                result.push(hud_chat_chars_to_component_line(&line, interactions, fonts));
                trim_chat_line_start(&mut carry);
                line = carry;
            } else {
                result.push(hud_chat_chars_to_component_line(&line, interactions, fonts));
                line.clear();
            }
            width = hud_chat_chars_width(&line, fonts);
            last_break = line
                .iter()
                .rposition(|value| value.ch.is_whitespace())
                .map(|index| index + 1);
        }
        if line.is_empty() && styled.ch.is_whitespace() {
            continue;
        }
        let whitespace = styled.ch.is_whitespace();
        line.push(styled);
        width += advance;
        if whitespace {
            last_break = Some(line.len());
        }
    }
    trim_chat_line_end(&mut line);
    if !line.is_empty() || result.is_empty() {
        result.push(hud_chat_chars_to_component_line(&line, interactions, fonts));
    }
    result
}

fn hud_chat_chars_width(chars: &[HudChatStyledChar], fonts: HudChatFontResolver<'_>) -> f32 {
    chars.iter().fold(0.0_f32, |width, styled| {
        width
            + hud_font_glyph(styled.ch, fonts.glyphs(styled.font.as_deref()))
                .styled_advance_f32(styled.style)
    })
}

fn trim_chat_line_start(chars: &mut Vec<HudChatStyledChar>) {
    let first = chars
        .iter()
        .position(|styled| !styled.ch.is_whitespace())
        .unwrap_or(chars.len());
    chars.drain(..first);
}

fn trim_chat_line_end(chars: &mut Vec<HudChatStyledChar>) {
    while chars.last().is_some_and(|styled| styled.ch.is_whitespace()) {
        chars.pop();
    }
}

fn hud_chat_chars_to_component_line(
    chars: &[HudChatStyledChar],
    source_interactions: &[HudChatInteraction],
    fonts: HudChatFontResolver<'_>,
) -> HudWrappedComponentChatLine {
    let mut runs = Vec::<HudComponentTextRun>::new();
    for styled in chars {
        if let Some(run) = runs.last_mut().filter(|run| {
            run.visual.style == styled.style
                && run.visual.color == styled.color
                && run.font == styled.font
        }) {
            run.visual.text.push(styled.ch);
        } else {
            runs.push(HudComponentTextRun {
                visual: HudStyledTextRun {
                    text: styled.ch.to_string(),
                    style: styled.style,
                    color: styled.color,
                },
                font: styled.font.clone(),
            });
        }
    }

    let logical = chars
        .iter()
        .cloned()
        .map(|styled| (styled.ch, styled))
        .collect::<Vec<_>>();
    let visual = visual_order(&logical, fonts.default_right_to_left());
    let mut interactions = Vec::<HudChatLineInteraction>::new();
    let mut x = 0.0_f32;
    for (ch, styled) in visual {
        let end = x + hud_font_glyph(ch, fonts.glyphs(styled.font.as_deref()))
            .styled_advance_f32(styled.style);
        let start_x = x.ceil() as u32;
        let end_x = end.ceil() as u32;
        if let Some(target_index) = styled.target_index {
            if let Some(previous) = interactions.last_mut().filter(|previous| {
                previous.target_index == target_index && previous.end_x == start_x
            }) {
                previous.end_x = end_x;
            } else {
                interactions.push(HudChatLineInteraction {
                    start_x,
                    end_x,
                    target_index,
                    tooltip: source_interactions
                        .iter()
                        .find(|interaction| interaction.target_index == target_index)
                        .and_then(|interaction| interaction.tooltip.clone()),
                });
            }
        }
        x = end;
    }
    HudWrappedComponentChatLine { runs, interactions }
}

fn hud_chat_hit_target_at(
    lines: &[HudChatLine],
    context: &HudChatContext,
    fonts: &HudFontGlyphBook,
    surface_size: PhysicalSize<u32>,
    position: (f64, f64),
) -> Option<HudChatHitTarget> {
    const MESSAGE_HEIGHT: i32 = 9;
    const BOTTOM_MARGIN: i32 = 40;
    if !context.focused || !position.0.is_finite() || !position.1.is_finite() {
        return None;
    }
    let x = position.0.floor() as i32;
    let y = position.1.floor() as i32;
    let chat_bottom = i32::try_from(surface_size.height)
        .unwrap_or(i32::MAX)
        .saturating_sub(BOTTOM_MARGIN);
    if let Some(restricted_text) = context.restricted_text.as_deref() {
        let visible_count = lines
            .iter()
            .rev()
            .skip(context.scroll_lines)
            .take(20)
            .filter(|line| hud_chat_line_alpha(context, line) > 1.0e-5)
            .count();
        let restricted_y = chat_bottom.saturating_sub(
            i32::try_from(visible_count.saturating_add(1))
                .unwrap_or(i32::MAX)
                .saturating_mul(MESSAGE_HEIGHT),
        );
        let text_width = hud_plain_text_width(restricted_text, fonts.glyphs(None));
        if (4..4 + i32::try_from(text_width).unwrap_or(i32::MAX)).contains(&x)
            && (restricted_y..restricted_y.saturating_add(MESSAGE_HEIGHT)).contains(&y)
        {
            return Some(HudChatHitTarget {
                level_generation: context.level_generation,
                delivery_revision: context.delivery_revision,
                chat_screen_revision: context.chat_screen_revision,
                resource_generation: context.resource_generation,
                resources_loaded: context.resources_loaded,
                kind: HudChatHitTargetKind::Restrictions,
            });
        }
    }
    if context.queued_messages > 0
        && (2..2 + HUD_CHAT_MAX_WIDTH as i32 + 6).contains(&x)
        && (chat_bottom..chat_bottom.saturating_add(MESSAGE_HEIGHT)).contains(&y)
    {
        return Some(HudChatHitTarget {
            level_generation: context.level_generation,
            delivery_revision: context.delivery_revision,
            chat_screen_revision: context.chat_screen_revision,
            resource_generation: context.resource_generation,
            resources_loaded: context.resources_loaded,
            kind: HudChatHitTargetKind::Queue,
        });
    }
    let (line, interaction) =
        hud_chat_line_and_interaction_at(lines, context, surface_size, position)?;
    Some(HudChatHitTarget {
        level_generation: context.level_generation,
        delivery_revision: context.delivery_revision,
        chat_screen_revision: context.chat_screen_revision,
        resource_generation: context.resource_generation,
        resources_loaded: context.resources_loaded,
        kind: HudChatHitTargetKind::Message {
            display_sequence: line.display_sequence,
            target_index: interaction.target_index,
        },
    })
}

fn hud_chat_line_interaction_at<'a>(
    lines: &'a [HudChatLine],
    context: &HudChatContext,
    surface_size: PhysicalSize<u32>,
    position: (f64, f64),
) -> Option<&'a HudChatLineInteraction> {
    hud_chat_line_and_interaction_at(lines, context, surface_size, position)
        .map(|(_, interaction)| interaction)
}

fn hud_chat_line_and_interaction_at<'a>(
    lines: &'a [HudChatLine],
    context: &HudChatContext,
    surface_size: PhysicalSize<u32>,
    position: (f64, f64),
) -> Option<(&'a HudChatLine, &'a HudChatLineInteraction)> {
    const MESSAGE_HEIGHT: i32 = 9;
    const BOTTOM_MARGIN: i32 = 40;
    if !context.focused || !position.0.is_finite() || !position.1.is_finite() {
        return None;
    }
    let x = position.0.floor() as i32;
    let y = position.1.floor() as i32;
    let chat_bottom = i32::try_from(surface_size.height)
        .unwrap_or(i32::MAX)
        .saturating_sub(BOTTOM_MARGIN);
    if x < 4 || y >= chat_bottom {
        return None;
    }
    let row = chat_bottom.saturating_sub(1).saturating_sub(y) / MESSAGE_HEIGHT;
    if !(0..20).contains(&row) {
        return None;
    }
    let line = lines
        .iter()
        .rev()
        .skip(context.scroll_lines)
        .nth(row as usize)?;
    let local_x = u32::try_from(x.saturating_sub(4)).ok()?;
    let interaction = line
        .interactions
        .iter()
        .find(|interaction| (interaction.start_x..interaction.end_x).contains(&local_x))?;
    Some((line, interaction))
}

fn hud_chat_tag_at<'a>(
    lines: &'a [HudChatLine],
    context: &HudChatContext,
    surface_size: PhysicalSize<u32>,
    position: (f64, f64),
    fonts: &HudFontGlyphBook,
) -> Option<&'a HudChatTag> {
    const MESSAGE_HEIGHT: i32 = 9;
    const BOTTOM_MARGIN: i32 = 40;
    if !context.focused || !position.0.is_finite() || !position.1.is_finite() {
        return None;
    }
    let x = position.0.floor() as i32;
    let y = position.1.floor() as i32;
    let chat_bottom = i32::try_from(surface_size.height)
        .unwrap_or(i32::MAX)
        .saturating_sub(BOTTOM_MARGIN);
    if y >= chat_bottom {
        return None;
    }
    let row = chat_bottom.saturating_sub(1).saturating_sub(y) / MESSAGE_HEIGHT;
    if !(0..20).contains(&row) {
        return None;
    }
    let line = lines
        .iter()
        .rev()
        .skip(context.scroll_lines)
        .nth(row as usize)?;
    let tag = line.tag.as_ref()?;
    if (0..2).contains(&x) {
        return Some(tag);
    }
    if line.end_of_entry && tag.kind == HudChatTagKind::Modified {
        let icon_x = i32::try_from(hud_component_runs_width(&line.runs, fonts).unwrap_or_default())
            .unwrap_or(i32::MAX)
            .saturating_add(8);
        if (icon_x..icon_x.saturating_add(9)).contains(&x) {
            return Some(tag);
        }
    }
    None
}

/// Vanilla `FontSet.computeGlyphInfo` walks the flattened provider chain; the
/// baked `HudFontGlyphMap` already encodes that first-provider-wins order, so
/// lookup is direct, with `?` standing in for codepoints no resolved provider
/// covers.
fn hud_font_glyph(ch: char, glyphs: &HudFontGlyphMap) -> HudAsciiGlyph {
    glyphs
        .get(ch)
        .or_else(|| glyphs.get(HUD_FONT_REPLACEMENT_GLYPH))
        .unwrap_or_default()
}

fn sanitize_hud_uv_rect(rect: HudUvRect) -> Option<HudUvRect> {
    let components = [rect.min[0], rect.min[1], rect.max[0], rect.max[1]];
    if !components.iter().all(|component| component.is_finite()) {
        return None;
    }

    let min_x = rect.min[0].clamp(0.0, 1.0);
    let min_y = rect.min[1].clamp(0.0, 1.0);
    let max_x = rect.max[0].clamp(0.0, 1.0);
    let max_y = rect.max[1].clamp(0.0, 1.0);
    Some(HudUvRect {
        min: [min_x.min(max_x), min_y.min(max_y)],
        max: [min_x.max(max_x), min_y.max(max_y)],
    })
}

fn sanitize_hud_hotbar_item_uv(uv: HudUvRect) -> Option<HudItemIcon> {
    sanitize_hud_item_icon(HudItemIcon::single(uv))
}

fn sanitize_hud_inventory_screen(screen: HudInventoryScreen) -> HudInventoryScreen {
    let background_layers = screen
        .background_layers
        .into_iter()
        .filter_map(sanitize_hud_inventory_background_layer)
        .collect::<Vec<_>>();
    let map_previews = screen
        .map_previews
        .into_iter()
        .filter(|preview| {
            preview.map_id >= 0
                && preview.scale.is_finite()
                && preview.scale > 0.0
                && preview.scale <= 4.0
                && preview.after_background_layer < background_layers.len()
        })
        .take(MAX_HUD_INVENTORY_MAP_PREVIEWS)
        .collect();
    let banner_pattern_previews = screen
        .banner_pattern_previews
        .into_iter()
        .filter_map(|mut preview| {
            if preview.width == 0
                || preview.height == 0
                || preview.width > 64
                || preview.height > 64
                || preview.after_background_layer >= background_layers.len()
            {
                return None;
            }
            preview.uv = sanitize_hud_uv_rect(preview.uv)?;
            Some(preview)
        })
        .take(MAX_HUD_INVENTORY_BANNER_PATTERN_PREVIEWS)
        .collect();
    let background_layer_count = background_layers.len();
    HudInventoryScreen {
        width: screen.width.clamp(1, 512),
        height: screen.height.clamp(1, 512),
        background_layers,
        foreground_layers: screen
            .foreground_layers
            .into_iter()
            .filter_map(sanitize_hud_inventory_background_layer)
            .collect(),
        fill_layers: screen
            .fill_layers
            .into_iter()
            .filter_map(sanitize_hud_inventory_fill_layer)
            .collect(),
        slots: screen
            .slots
            .into_iter()
            .map(sanitize_hud_inventory_slot)
            .collect(),
        floating_items: screen
            .floating_items
            .into_iter()
            .filter_map(sanitize_hud_inventory_item)
            .collect(),
        foreground_items: screen
            .foreground_items
            .into_iter()
            .filter_map(sanitize_hud_inventory_item)
            .collect(),
        ghost_items: screen
            .ghost_items
            .into_iter()
            .filter_map(sanitize_hud_inventory_ghost_item)
            .collect(),
        entity_previews: screen
            .entity_previews
            .into_iter()
            .filter_map(sanitize_hud_entity_preview)
            .filter(|preview| {
                preview
                    .after_background_layer
                    .is_none_or(|layer| layer < background_layer_count)
            })
            .collect(),
        map_previews,
        banner_pattern_previews,
        text_labels: screen
            .text_labels
            .into_iter()
            .filter_map(sanitize_hud_inventory_text_label)
            .collect(),
        scroll_area: screen
            .scroll_area
            .and_then(sanitize_hud_inventory_scroll_area),
        preedit_overlay: screen
            .preedit_overlay
            .and_then(sanitize_hud_inventory_preedit_overlay),
        hovered_slot_id: screen.hovered_slot_id,
        tooltip: screen.tooltip.and_then(sanitize_hud_inventory_tooltip),
    }
}

fn sanitize_hud_inventory_preedit_overlay(
    mut overlay: HudInventoryPreeditOverlay,
) -> Option<HudInventoryPreeditOverlay> {
    if overlay.background_width == 0 || overlay.background_height == 0 {
        return None;
    }
    overlay.text = sanitize_hud_text_preserving_empty(overlay.text, 256);
    if overlay.text.is_empty() {
        return None;
    }
    let text_len = overlay.text.chars().count();
    overlay.focused_start = overlay.focused_start.min(text_len);
    overlay.focused_end = overlay.focused_end.clamp(overlay.focused_start, text_len);
    overlay.caret = overlay.caret.map(|caret| caret.min(text_len));
    overlay.background_width = overlay.background_width.min(2048);
    overlay.background_height = overlay.background_height.min(512);
    Some(overlay)
}

fn sanitize_hud_inventory_scroll_area(
    area: HudInventoryScrollArea,
) -> Option<HudInventoryScrollArea> {
    let scissor = sanitize_hud_inventory_item_scissor(area.scissor)?;
    Some(HudInventoryScrollArea {
        scissor,
        background_layers: area
            .background_layers
            .into_iter()
            .filter_map(sanitize_hud_inventory_background_layer)
            .collect(),
        fill_layers: area
            .fill_layers
            .into_iter()
            .filter_map(sanitize_hud_inventory_fill_layer)
            .collect(),
        text_labels: area
            .text_labels
            .into_iter()
            .filter_map(sanitize_hud_inventory_text_label)
            .collect(),
        text_areas: area
            .text_areas
            .into_iter()
            .filter_map(sanitize_hud_inventory_text_area)
            .collect(),
        scrollbar: area.scrollbar.and_then(sanitize_hud_inventory_scrollbar),
    })
}

fn sanitize_hud_inventory_text_area(
    mut area: HudInventoryTextArea,
) -> Option<HudInventoryTextArea> {
    if area.width == 0
        || area.height == 0
        || !area
            .text_tint
            .iter()
            .chain(area.cursor_tint.iter())
            .chain(area.selection_tint.iter())
            .chain(area.counter_tint.iter())
            .all(|component| component.is_finite())
    {
        return None;
    }
    area.width = area.width.min(1024);
    area.height = area.height.min(512);
    area.max_length = area.max_length.min(1024);
    area.text = sanitize_hud_multiline_text(area.text, area.max_length);
    let text_len = area.text.chars().count();
    area.cursor = area.cursor.min(text_len);
    area.selection = area.selection.min(text_len);
    area.scroll_amount = area.scroll_amount.max(0);
    area.text_tint = area.text_tint.map(|component| component.clamp(0.0, 1.0));
    area.cursor_tint = area.cursor_tint.map(|component| component.clamp(0.0, 1.0));
    area.selection_tint = area
        .selection_tint
        .map(|component| component.clamp(0.0, 1.0));
    area.counter_tint = area.counter_tint.map(|component| component.clamp(0.0, 1.0));
    Some(area)
}

fn sanitize_hud_inventory_scrollbar(
    scrollbar: HudInventoryScrollbar,
) -> Option<HudInventoryScrollbar> {
    if scrollbar.width == 0 || scrollbar.height == 0 || scrollbar.thumb_height == 0 {
        return None;
    }
    let width = scrollbar.width.min(512);
    let height = scrollbar.height.min(512);
    let thumb_height = scrollbar.thumb_height.min(height);
    let thumb_y = scrollbar.thumb_y.clamp(
        scrollbar.y,
        scrollbar
            .y
            .saturating_add(i32::try_from(height.saturating_sub(thumb_height)).unwrap_or(i32::MAX)),
    );
    Some(HudInventoryScrollbar {
        width,
        height,
        thumb_y,
        thumb_height,
        ..scrollbar
    })
}

fn sanitize_hud_sign_editor_screen(mut screen: HudSignEditorScreen) -> Option<HudSignEditorScreen> {
    if !screen
        .text_tint
        .iter()
        .all(|component| component.is_finite())
    {
        return None;
    }
    screen.title = sanitize_hud_text_preserving_empty(screen.title, 256);
    if screen.title.is_empty() {
        return None;
    }
    screen.lines = screen
        .lines
        .map(|line| sanitize_hud_text_preserving_empty(line, usize::MAX));
    screen.line = screen.line.min(screen.lines.len().saturating_sub(1));
    let line_len = screen.lines[screen.line].chars().count();
    screen.cursor = screen.cursor.min(line_len);
    screen.selection = screen.selection.min(line_len);
    screen.text_tint = screen.text_tint.map(|component| component.clamp(0.0, 1.0));
    screen.done = sanitize_hud_text_preserving_empty(screen.done, 256);
    if screen.done.is_empty() {
        return None;
    }
    screen.preedit = screen.preedit.and_then(sanitize_hud_sign_editor_preedit);
    screen.sign_preview = match screen.kind {
        HudSignEditorKind::Standing { .. } => {
            screen.sign_preview.and_then(sanitize_hud_entity_preview)
        }
        HudSignEditorKind::Hanging { .. } => None,
    };
    Some(screen)
}

fn sanitize_hud_sign_editor_preedit(
    mut preedit: HudSignEditorPreedit,
) -> Option<HudSignEditorPreedit> {
    preedit.text = sanitize_hud_text_preserving_empty(preedit.text, 256);
    if preedit.text.is_empty() {
        return None;
    }
    let text_len = preedit.text.chars().count();
    preedit.focused_start = preedit.focused_start.min(text_len);
    preedit.focused_end = preedit.focused_end.clamp(preedit.focused_start, text_len);
    preedit.caret = preedit.caret.map(|caret| caret.min(text_len));
    Some(preedit)
}

fn sanitize_hud_command_block_editor_screen(
    mut screen: HudCommandBlockEditorScreen,
) -> Option<HudCommandBlockEditorScreen> {
    screen.title = sanitize_hud_text_preserving_empty(screen.title, 256);
    screen.command_label = sanitize_hud_text_preserving_empty(screen.command_label, 256);
    screen.previous_output_label =
        sanitize_hud_text_preserving_empty(screen.previous_output_label, 256);
    screen.previous_output =
        sanitize_hud_text_preserving_empty_utf16(screen.previous_output, 32_500);
    screen.mode = sanitize_hud_text_preserving_empty(screen.mode, 256);
    screen.conditional = sanitize_hud_text_preserving_empty(screen.conditional, 256);
    screen.automatic = sanitize_hud_text_preserving_empty(screen.automatic, 256);
    screen.track_output = sanitize_hud_text_preserving_empty(screen.track_output, 16);
    screen.done = sanitize_hud_text_preserving_empty(screen.done, 256);
    screen.cancel = sanitize_hud_text_preserving_empty(screen.cancel, 256);
    (!screen.title.is_empty()
        && !screen.command_label.is_empty()
        && !screen.done.is_empty()
        && !screen.cancel.is_empty())
    .then_some(screen)
}

fn sanitize_hud_structure_block_editor_screen(
    mut screen: HudStructureBlockEditorScreen,
) -> Option<HudStructureBlockEditorScreen> {
    screen.title = sanitize_hud_text_preserving_empty(screen.title, 256);
    screen.name_label = sanitize_hud_text_preserving_empty(screen.name_label, 256);
    screen.position_label = sanitize_hud_text_preserving_empty(screen.position_label, 256);
    screen.size_label = sanitize_hud_text_preserving_empty(screen.size_label, 256);
    screen.integrity_label = sanitize_hud_text_preserving_empty(screen.integrity_label, 256);
    screen.data_label = sanitize_hud_text_preserving_empty(screen.data_label, 256);
    screen.include_entities_label =
        sanitize_hud_text_preserving_empty(screen.include_entities_label, 256);
    screen.strict_label = sanitize_hud_text_preserving_empty(screen.strict_label, 256);
    screen.detect_label = sanitize_hud_text_preserving_empty(screen.detect_label, 256);
    screen.option_label = sanitize_hud_text_preserving_empty(screen.option_label, 256);
    screen.mode_description = sanitize_hud_text_preserving_empty(screen.mode_description, 256);
    let fields = screen.fields.clone();
    screen.fields = std::array::from_fn(|index| {
        let max = match index {
            0 | 9 => 128,
            8 => 31,
            _ => 15,
        };
        sanitize_hud_structure_block_text_field(fields[index].clone(), max)
    });
    screen.mode_value = sanitize_hud_text_preserving_empty(screen.mode_value, 64);
    screen.mirror_value = sanitize_hud_text_preserving_empty(screen.mirror_value, 64);
    screen.rotation = sanitize_hud_text_preserving_empty(screen.rotation, 16);
    screen.include_entities = sanitize_hud_text_preserving_empty(screen.include_entities, 16);
    screen.strict = sanitize_hud_text_preserving_empty(screen.strict, 16);
    screen.option = sanitize_hud_text_preserving_empty(screen.option, 16);
    screen.action = sanitize_hud_text_preserving_empty(screen.action, 256);
    screen.detect = sanitize_hud_text_preserving_empty(screen.detect, 256);
    screen.done = sanitize_hud_text_preserving_empty(screen.done, 256);
    screen.cancel = sanitize_hud_text_preserving_empty(screen.cancel, 256);
    (!screen.title.is_empty()
        && !screen.mode_value.is_empty()
        && !screen.done.is_empty()
        && !screen.cancel.is_empty())
    .then_some(screen)
}

fn sanitize_hud_structure_block_text_field(
    mut field: HudStructureBlockEditorTextField,
    max_length: usize,
) -> HudStructureBlockEditorTextField {
    field.max_length = field.max_length.min(max_length);
    field.text = sanitize_hud_text_preserving_empty_utf16(field.text, field.max_length);
    let length = field.text.chars().count();
    field.cursor = field.cursor.min(length);
    field.selection = field.selection.min(length);
    field
}

fn sanitize_hud_jigsaw_block_editor_screen(
    mut screen: HudJigsawBlockEditorScreen,
) -> Option<HudJigsawBlockEditorScreen> {
    screen.labels = screen
        .labels
        .map(|label| sanitize_hud_text_preserving_empty(label, 256));
    screen.joint_label = sanitize_hud_text_preserving_empty(screen.joint_label, 256);
    let fields = screen.fields.clone();
    screen.fields = std::array::from_fn(|index| {
        let max = match index {
            0..=2 => 128,
            3 => 256,
            _ => 3,
        };
        sanitize_hud_jigsaw_block_text_field(fields[index].clone(), max)
    });
    screen.joint = sanitize_hud_text_preserving_empty(screen.joint, 64);
    screen.levels = sanitize_hud_text_preserving_empty(screen.levels, 64);
    let slider_value = f64::from_bits(screen.slider_value_bits);
    screen.slider_value_bits = if slider_value.is_finite() {
        slider_value.clamp(0.0, 1.0).to_bits()
    } else {
        0.0_f64.to_bits()
    };
    screen.keep_jigsaws = sanitize_hud_text_preserving_empty(screen.keep_jigsaws, 128);
    screen.generate = sanitize_hud_text_preserving_empty(screen.generate, 256);
    screen.done = sanitize_hud_text_preserving_empty(screen.done, 256);
    screen.cancel = sanitize_hud_text_preserving_empty(screen.cancel, 256);
    screen.tooltip = screen.tooltip.and_then(|mut tooltip| {
        tooltip.text = tooltip
            .text
            .chars()
            .filter(|ch| *ch == '\n' || !ch.is_control())
            .take(4096)
            .collect();
        (!tooltip.text.is_empty()).then_some(tooltip)
    });
    (screen.labels.iter().all(|label| !label.is_empty())
        && !screen.levels.is_empty()
        && !screen.generate.is_empty()
        && !screen.done.is_empty()
        && !screen.cancel.is_empty())
    .then_some(screen)
}

fn sanitize_hud_jigsaw_block_text_field(
    mut field: HudJigsawBlockEditorTextField,
    max_length: usize,
) -> HudJigsawBlockEditorTextField {
    field.max_length = field.max_length.min(max_length);
    field.text = sanitize_hud_text_preserving_empty_utf16(field.text, field.max_length);
    let length = field.text.chars().count();
    field.cursor = field.cursor.min(length);
    field.selection = field.selection.min(length);
    field
}

fn sanitize_hud_test_block_editor_screen(
    mut screen: HudTestBlockEditorScreen,
) -> Option<HudTestBlockEditorScreen> {
    screen.title = sanitize_hud_text_preserving_empty(screen.title, 256);
    screen.message_label = sanitize_hud_text_preserving_empty(screen.message_label, 256);
    screen.message.max_length = screen.message.max_length.min(128);
    screen.message.text =
        sanitize_hud_text_preserving_empty_utf16(screen.message.text, screen.message.max_length);
    let length = screen.message.text.chars().count();
    screen.message.cursor = screen.message.cursor.min(length);
    screen.message.selection = screen.message.selection.min(length);
    screen.mode = sanitize_hud_text_preserving_empty(screen.mode, 64);
    screen.mode_info = sanitize_hud_text_preserving_empty(screen.mode_info, 256);
    screen.done = sanitize_hud_text_preserving_empty(screen.done, 256);
    screen.cancel = sanitize_hud_text_preserving_empty(screen.cancel, 256);
    (!screen.title.is_empty()
        && !screen.message_label.is_empty()
        && !screen.mode.is_empty()
        && !screen.mode_info.is_empty()
        && !screen.done.is_empty()
        && !screen.cancel.is_empty())
    .then_some(screen)
}

fn sanitize_hud_test_instance_block_editor_screen(
    mut screen: HudTestInstanceBlockEditorScreen,
) -> Option<HudTestInstanceBlockEditorScreen> {
    screen.title = sanitize_hud_text_preserving_empty(screen.title, 256);
    screen.id_label = sanitize_hud_text_preserving_empty(screen.id_label, 256);
    screen.size_label = sanitize_hud_text_preserving_empty(screen.size_label, 256);
    screen.rotation_label = sanitize_hud_text_preserving_empty(screen.rotation_label, 256);
    screen.entities_label = sanitize_hud_text_preserving_empty(screen.entities_label, 256);
    screen.id = sanitize_hud_test_instance_block_text_field(screen.id, 128);
    screen.size = screen
        .size
        .map(|field| sanitize_hud_test_instance_block_text_field(field, 15));
    let mut info_budget = 4096usize;
    screen.info_runs = screen
        .info_runs
        .into_iter()
        .take(256)
        .filter_map(|run| {
            let text = run
                .text
                .chars()
                .filter(|ch| *ch == '\n' || !ch.is_control())
                .take(info_budget)
                .collect::<String>();
            info_budget = info_budget.saturating_sub(text.chars().count());
            (!text.is_empty()).then_some(HudStyledTextRun {
                text,
                style: run.style,
                color: run.color.map(|color| color & 0xFF_FF_FF),
            })
        })
        .collect();
    screen.rotation = sanitize_hud_text_preserving_empty(screen.rotation, 64);
    screen.include_entities = sanitize_hud_text_preserving_empty(screen.include_entities, 64);
    screen.reset = sanitize_hud_text_preserving_empty(screen.reset, 256);
    screen.save = sanitize_hud_text_preserving_empty(screen.save, 256);
    screen.run = sanitize_hud_text_preserving_empty(screen.run, 256);
    screen.done = sanitize_hud_text_preserving_empty(screen.done, 256);
    screen.cancel = sanitize_hud_text_preserving_empty(screen.cancel, 256);
    (!screen.title.is_empty()
        && !screen.id_label.is_empty()
        && !screen.size_label.is_empty()
        && !screen.done.is_empty()
        && !screen.cancel.is_empty())
    .then_some(screen)
}

fn sanitize_hud_test_instance_block_text_field(
    mut field: HudTestInstanceBlockEditorTextField,
    max_length: usize,
) -> HudTestInstanceBlockEditorTextField {
    field.max_length = field.max_length.min(max_length);
    field.text = sanitize_hud_text_preserving_empty_utf16(field.text, field.max_length);
    let length = field.text.chars().count();
    field.cursor = field.cursor.min(length);
    field.selection = field.selection.min(length);
    field
}

fn sanitize_hud_inventory_background_layer(
    mut layer: HudInventoryBackgroundLayer,
) -> Option<HudInventoryBackgroundLayer> {
    if let HudInventoryBackgroundTexture::SmithingSlotIcon {
        icon, alpha_bits, ..
    } = layer.texture
    {
        let alpha = f32::from_bits(alpha_bits);
        if !alpha.is_finite() {
            return None;
        }
        layer.texture = HudInventoryBackgroundTexture::smithing_slot_icon(icon, alpha);
    }
    let uv = match layer.texture {
        HudInventoryBackgroundTexture::InworldMenuBackground => {
            sanitize_repeating_hud_uv_rect(layer.uv)?
        }
        _ => sanitize_hud_uv_rect(layer.uv)?,
    };
    (layer.width > 0 && layer.height > 0).then_some(HudInventoryBackgroundLayer { uv, ..layer })
}

fn sanitize_repeating_hud_uv_rect(rect: HudUvRect) -> Option<HudUvRect> {
    let components = [rect.min[0], rect.min[1], rect.max[0], rect.max[1]];
    if !components.iter().all(|component| component.is_finite()) {
        return None;
    }
    Some(HudUvRect {
        min: [rect.min[0].min(rect.max[0]), rect.min[1].min(rect.max[1])],
        max: [rect.min[0].max(rect.max[0]), rect.min[1].max(rect.max[1])],
    })
}

fn sanitize_hud_inventory_fill_layer(
    layer: HudInventoryFillLayer,
) -> Option<HudInventoryFillLayer> {
    if layer.width == 0
        || layer.height == 0
        || !layer.tint.iter().all(|component| component.is_finite())
    {
        return None;
    }
    Some(HudInventoryFillLayer {
        tint: layer.tint.map(|component| component.clamp(0.0, 1.0)),
        ..layer
    })
}

fn sanitize_hud_inventory_slot(slot: HudInventorySlot) -> HudInventorySlot {
    HudInventorySlot {
        slot_id: slot.slot_id,
        x: slot.x,
        y: slot.y,
        icon: slot.icon.and_then(sanitize_hud_item_icon),
        block_model: slot.block_model.filter(hud_block_item_model_is_renderable),
    }
}

fn sanitize_hud_inventory_item(item: HudInventoryItem) -> Option<HudInventoryItem> {
    if !item.scale.is_finite()
        || item.scale <= 0.0
        || !item.scale_y.is_finite()
        || item.scale_y <= 0.0
    {
        return None;
    }
    let scale = item.scale.clamp(0.0625, 16.0);
    let scale_y = item.scale_y.clamp(0.0625, 16.0);
    let scissor = item.scissor.and_then(sanitize_hud_inventory_item_scissor);
    Some(HudInventoryItem {
        x: item.x,
        y: item.y,
        scale,
        scale_y,
        icon: sanitize_hud_item_icon(item.icon)?,
        scissor,
        draw_decorations: item.draw_decorations,
        block_model: item.block_model.filter(hud_block_item_model_is_renderable),
    })
}

fn sanitize_hud_inventory_item_scissor(
    scissor: HudInventoryItemScissor,
) -> Option<HudInventoryItemScissor> {
    (scissor.width > 0 && scissor.height > 0).then_some(HudInventoryItemScissor {
        width: scissor.width.min(512),
        height: scissor.height.min(512),
        ..scissor
    })
}

fn sanitize_hud_inventory_ghost_item(item: HudInventoryGhostItem) -> Option<HudInventoryGhostItem> {
    Some(HudInventoryGhostItem {
        x: item.x,
        y: item.y,
        icon: sanitize_hud_item_icon(item.icon)?,
        draw_decorations: item.draw_decorations,
    })
}

/// A 3D block-item icon is only worth carrying when it has geometry to draw.
fn hud_block_item_model_is_renderable(model: &HudBlockItemModel) -> bool {
    model.lighting == GuiItemLightingEntry::Items3d && !model.layers.is_empty()
}

fn sign_model_wood_index(wood: SignModelWood) -> usize {
    match wood {
        SignModelWood::Oak => 0,
        SignModelWood::Spruce => 1,
        SignModelWood::Birch => 2,
        SignModelWood::Acacia => 3,
        SignModelWood::Cherry => 4,
        SignModelWood::Jungle => 5,
        SignModelWood::DarkOak => 6,
        SignModelWood::PaleOak => 7,
        SignModelWood::Crimson => 8,
        SignModelWood::Warped => 9,
        SignModelWood::Mangrove => 10,
        SignModelWood::Bamboo => 11,
    }
}

/// The PIP-texture sub-rect (as `0..1` UV fractions of the preview rect) a scissored blit
/// samples: `visible == rect ∩ scissor` maps to the matching texture region, identity UVs when
/// no scissor applies. Vanilla scissors the full-rect blit instead; for an axis-aligned scissor
/// the two are pixel-equivalent. wgpu's row-0-top texture origin means the PIP render is already
/// GUI-oriented — vanilla's `v0=1, v1=0` vertical flip is a GL framebuffer-origin artifact and
/// has no bbb counterpart.
fn hud_entity_preview_blit_uv(
    rect: HudEntityPreviewRect,
    visible: HudEntityPreviewRect,
) -> HudUvRect {
    let width = rect.width.max(1) as f32;
    let height = rect.height.max(1) as f32;
    HudUvRect {
        min: [
            (visible.x - rect.x) as f32 / width,
            (visible.y - rect.y) as f32 / height,
        ],
        max: [
            (visible.right() - i64::from(rect.x)) as f32 / width,
            (visible.bottom() - i64::from(rect.y)) as f32 / height,
        ],
    }
}

fn sanitize_hud_entity_preview(mut preview: HudEntityPreview) -> Option<HudEntityPreview> {
    let is_flat_gui_preview = is_flat_gui_preview(&preview);
    if (!is_flat_gui_preview && preview.lighting != GuiItemLightingEntry::EntityInUi)
        || !preview.depth_isolated
    {
        return None;
    }
    preview.rect = sanitize_hud_entity_preview_rect(preview.rect)?;
    preview.scissor = match preview.scissor {
        Some(scissor) => Some(sanitize_hud_entity_preview_rect(scissor)?),
        None => None,
    };
    preview.visible_bounds()?;
    if !preview.scale.is_finite() || preview.scale <= 0.0 {
        return None;
    }
    if !preview
        .translation
        .iter()
        .all(|component| component.is_finite())
        || !preview
            .rotation
            .iter()
            .all(|component| component.is_finite())
        || !preview
            .override_camera_rotation
            .map(|rotation| rotation.iter().all(|component| component.is_finite()))
            .unwrap_or(true)
    {
        return None;
    }

    preview.entity.render_state.light_coords = ENTITY_FULL_BRIGHT_LIGHT_COORDS;
    preview.entity.render_state.outline_color = 0;
    preview.entity.render_state.appears_glowing = false;
    for layer in &mut preview.item_layers {
        if layer.item_id < 0 || layer.count <= 0 {
            return None;
        }
        layer.light_coords = ENTITY_FULL_BRIGHT_LIGHT_COORDS;
        layer.overlay = ITEM_MODEL_NO_OVERLAY;
    }
    Some(preview)
}

fn is_flat_gui_preview(preview: &HudEntityPreview) -> bool {
    preview.lighting == GuiItemLightingEntry::ItemsFlat
        && matches!(
            preview.entity.kind,
            crate::entity_models::EntityModelKind::Sign { .. }
                | crate::entity_models::EntityModelKind::Banner {
                    flag_only: true,
                    ..
                }
        )
}

fn sanitize_hud_entity_preview_rect(rect: HudEntityPreviewRect) -> Option<HudEntityPreviewRect> {
    // Preview bounds live inside the (512-clamped) inventory screen; the clamp also bounds the
    // per-preview PIP color/depth texture allocation.
    (rect.width > 0 && rect.height > 0).then_some(HudEntityPreviewRect {
        width: rect.width.min(512),
        height: rect.height.min(512),
        ..rect
    })
}

fn sanitize_hud_inventory_text_label(
    label: HudInventoryTextLabel,
) -> Option<HudInventoryTextLabel> {
    if !label.tint.iter().all(|component| component.is_finite()) {
        return None;
    }
    let x = label.x;
    let y = label.y;
    let width = label.width;
    let tint = label.tint;
    let background = label
        .background
        .and_then(sanitize_hud_inventory_text_background);
    let text = if label.input.is_some() {
        sanitize_hud_text_preserving_empty(label.text, 256)
    } else {
        sanitize_hud_text_line(label.text)?
    };
    let input = label
        .input
        .and_then(|input| sanitize_hud_inventory_text_input(input, &text));
    let scrolling = if input.is_none() {
        label
            .scrolling
            .and_then(sanitize_hud_inventory_scrolling_text)
    } else {
        None
    };
    let font = label
        .font
        .map(|font| sanitize_hud_text_preserving_empty(font, 256))
        .filter(|font| !font.is_empty());
    if text.is_empty() && input.is_none() {
        return None;
    }
    let runs = sanitize_hud_styled_runs(label.runs, &text);
    (width > 0).then_some(HudInventoryTextLabel {
        x,
        y,
        width: width.min(512),
        text,
        tint: tint.map(|component| component.clamp(0.0, 1.0)),
        background,
        input,
        scrolling,
        shadow: label.shadow,
        font,
        runs,
    })
}

fn sanitize_hud_inventory_scrolling_text(
    scrolling: HudInventoryScrollingText,
) -> Option<HudInventoryScrollingText> {
    (scrolling.width > 0 && scrolling.height > 0).then_some(HudInventoryScrollingText {
        width: scrolling.width.min(1024),
        height: scrolling.height.min(512),
        ..scrolling
    })
}

fn sanitize_hud_inventory_text_input(
    input: HudInventoryTextInputDecoration,
    text: &str,
) -> Option<HudInventoryTextInputDecoration> {
    if !input
        .cursor_tint
        .iter()
        .chain(input.selection_tint.iter())
        .all(|component| component.is_finite())
    {
        return None;
    }
    let len = text.chars().count();
    Some(HudInventoryTextInputDecoration {
        cursor: input.cursor.min(len),
        selection: input.selection.min(len),
        scroll_to: input.scroll_to.min(len),
        max_length: input.max_length.min(1024),
        cursor_visible: input.cursor_visible,
        cursor_tint: input.cursor_tint.map(|component| component.clamp(0.0, 1.0)),
        selection_tint: input
            .selection_tint
            .map(|component| component.clamp(0.0, 1.0)),
    })
}

fn sanitize_hud_inventory_text_background(
    background: HudInventoryTextBackground,
) -> Option<HudInventoryTextBackground> {
    if !background
        .tint
        .iter()
        .all(|component| component.is_finite())
    {
        return None;
    }
    (background.width > 0 && background.height > 0).then_some(HudInventoryTextBackground {
        width: background.width.min(512),
        height: background.height.min(512),
        tint: background.tint.map(|component| component.clamp(0.0, 1.0)),
        ..background
    })
}

fn sanitize_hud_inventory_tooltip(tooltip: HudInventoryTooltip) -> Option<HudInventoryTooltip> {
    let lines = tooltip
        .lines
        .into_iter()
        .filter_map(sanitize_hud_inventory_tooltip_line)
        .take(16)
        .collect::<Vec<_>>();
    lines
        .iter()
        .any(|line| !line.text.is_empty())
        .then_some(HudInventoryTooltip { lines, ..tooltip })
}

fn sanitize_hud_inventory_tooltip_line(
    line: HudInventoryTooltipLine,
) -> Option<HudInventoryTooltipLine> {
    if !line.tint.iter().all(|component| component.is_finite()) {
        return None;
    }
    // Empty Components are meaningful vertical separators in vanilla item and
    // enchanting tooltips, so retain them while still stripping controls.
    let text = sanitize_hud_text_preserving_empty(line.text, 256);
    let mut budget = 256usize;
    let runs = sanitize_hud_component_runs(line.runs, &text, &mut budget, false);
    Some(HudInventoryTooltipLine {
        text,
        tint: line.tint.map(|component| component.clamp(0.0, 1.0)),
        runs,
    })
}

fn sanitize_hud_debug_overlay(overlay: HudDebugOverlay) -> Option<HudDebugOverlay> {
    let left_lines = sanitize_hud_debug_overlay_lines(overlay.left_lines);
    let right_lines = sanitize_hud_debug_overlay_lines(overlay.right_lines);
    let debug_crosshair = overlay
        .debug_crosshair
        .and_then(sanitize_hud_debug_crosshair);
    let game_mode_switcher = overlay
        .game_mode_switcher
        .and_then(sanitize_hud_debug_game_mode_switcher);
    let profiler_chart = overlay
        .profiler_chart
        .map(sanitize_hud_debug_profiler_chart);
    let fps_chart = overlay.fps_chart.map(sanitize_hud_debug_fps_chart);
    let tps_chart = overlay.tps_chart.map(sanitize_hud_debug_tps_chart);
    let network_charts = overlay
        .network_charts
        .map(sanitize_hud_debug_network_charts);
    (!left_lines.is_empty()
        || !right_lines.is_empty()
        || debug_crosshair.is_some()
        || game_mode_switcher.is_some()
        || profiler_chart.is_some()
        || fps_chart.is_some()
        || tps_chart.is_some()
        || network_charts.is_some()
        || overlay.show_lightmap_preview)
        .then_some(HudDebugOverlay {
            left_lines,
            right_lines,
            debug_crosshair,
            game_mode_switcher,
            profiler_chart,
            fps_chart,
            tps_chart,
            network_charts,
            show_lightmap_preview: overlay.show_lightmap_preview,
        })
}

fn sanitize_hud_debug_game_mode_switcher(
    switcher: HudDebugGameModeSwitcher,
) -> Option<HudDebugGameModeSwitcher> {
    let title = sanitize_hud_text_line(switcher.title)?;
    let help_text = sanitize_hud_text_line(switcher.help_text)?;
    let slots = switcher
        .slots
        .into_iter()
        .filter_map(sanitize_hud_debug_game_mode_switcher_slot)
        .take(4)
        .collect::<Vec<_>>();
    (switcher.background_width > 0 && switcher.background_height > 0 && slots.len() == 4).then_some(
        HudDebugGameModeSwitcher {
            title,
            help_text,
            slots,
            ..switcher
        },
    )
}

fn sanitize_hud_pause_screen(screen: HudPauseScreen) -> Option<HudPauseScreen> {
    let title = sanitize_hud_text_line(screen.title)?;
    let custom_dialog_label = screen
        .custom_dialog_label
        .map(|label| sanitize_hud_text_preserving_empty(label, 256));
    let custom_dialog_tooltip = screen.custom_dialog_tooltip.and_then(|tooltip| {
        let text = sanitize_hud_multiline_text(tooltip.text, 512);
        (!text.is_empty()).then_some(HudPauseScreenTooltip { text, ..tooltip })
    });
    let draft_confirmation = screen.draft_confirmation.and_then(|confirmation| {
        let title = sanitize_hud_text_line(confirmation.title)?;
        let message = sanitize_hud_multiline_text(confirmation.message, 512);
        let edit_label = sanitize_hud_text_line(confirmation.edit_label)?;
        let discard_label = sanitize_hud_text_line(confirmation.discard_label)?;
        (!title.is_empty()).then_some(HudPauseDraftConfirmationScreen {
            title,
            message,
            edit_label,
            discard_label,
            hovered: confirmation.hovered,
        })
    });
    (!title.is_empty()).then_some(HudPauseScreen {
        title,
        show_pause_menu: screen.show_pause_menu,
        feedback_subscreen: screen.feedback_subscreen,
        return_to_game_hovered: screen.return_to_game_hovered,
        advancements_hovered: screen.advancements_hovered,
        stats_hovered: screen.stats_hovered,
        send_feedback_hovered: screen.send_feedback_hovered,
        report_bugs_hovered: screen.report_bugs_hovered,
        report_bugs_enabled: screen.report_bugs_enabled,
        custom_dialog_label,
        custom_dialog_hovered: screen.custom_dialog_hovered,
        custom_dialog_tooltip,
        feedback_back_hovered: screen.feedback_back_hovered,
        options_hovered: screen.options_hovered,
        options_enabled: screen.options_enabled,
        player_reporting_hovered: screen.player_reporting_hovered,
        player_reporting_enabled: screen.player_reporting_enabled,
        disconnect_hovered: screen.disconnect_hovered,
        disconnect_enabled: screen.disconnect_enabled,
        has_draft_report: screen.has_draft_report,
        draft_confirmation,
    })
}

fn sanitize_hud_stats_screen(screen: HudStatsScreen) -> Option<HudStatsScreen> {
    let title = sanitize_hud_text_line(screen.title)?;
    let loading_text = sanitize_hud_text_line(screen.loading_text)?;
    let general_tab = sanitize_hud_text_line(screen.general_tab)?;
    let items_tab = sanitize_hud_text_line(screen.items_tab)?;
    let mobs_tab = sanitize_hud_text_line(screen.mobs_tab)?;
    let item_column_labels = screen
        .item_column_labels
        .into_iter()
        .map(sanitize_hud_text_line)
        .collect::<Option<Vec<_>>>()?
        .try_into()
        .ok()?;
    let item_no_value = sanitize_hud_text_line(screen.item_no_value)?;
    let tooltip = screen.tooltip.and_then(sanitize_hud_debug_options_tooltip);
    let visible_rows = screen.visible_rows.min(64);
    let max_scroll_amount = screen.max_scroll_amount.clamp(0, 1_000_000);
    let scroll_amount = screen.scroll_amount.clamp(0, max_scroll_amount);
    let scroller_height = if max_scroll_amount > 0 {
        screen.scroller_height.clamp(1, 4096)
    } else {
        0
    };
    let rows = screen
        .rows
        .into_iter()
        .filter_map(|row| {
            Some(HudStatsRow {
                label: sanitize_hud_text_line(row.label)?,
                value: sanitize_hud_text_line(row.value)?,
                secondary_value: row.secondary_value.and_then(sanitize_hud_text_line),
            })
        })
        .take(visible_rows)
        .collect();
    let item_rows = screen
        .item_rows
        .into_iter()
        .filter_map(|row| {
            Some(HudStatsItemRow {
                item_id: row.item_id,
                resource_id: sanitize_hud_text_line(row.resource_id)?,
                label: sanitize_hud_text_line(row.label)?,
                values: row
                    .values
                    .map(|value| value.and_then(sanitize_hud_text_line)),
                icon: row.icon.and_then(sanitize_hud_item_icon),
                block_model: row.block_model.filter(hud_block_item_model_is_renderable),
            })
        })
        .take(visible_rows)
        .collect();
    (!title.is_empty() && !loading_text.is_empty()).then_some(HudStatsScreen {
        title,
        loading_text,
        is_loading: screen.is_loading,
        general_tab,
        items_tab,
        mobs_tab,
        active_tab: screen.active_tab.min(2),
        items_tab_enabled: screen.items_tab_enabled,
        mobs_tab_enabled: screen.mobs_tab_enabled,
        rows,
        item_rows,
        item_column_labels,
        item_no_value,
        item_sort_column: screen.item_sort_column.filter(|column| *column < 6),
        item_sort_order: screen.item_sort_order.clamp(-1, 1),
        item_hovered_column: screen.item_hovered_column.filter(|column| *column < 6),
        item_focused_column: screen.item_focused_column.filter(|column| *column < 6),
        scroll_row: screen.scroll_row.min(screen.total_rows),
        scroll_amount,
        max_scroll_amount,
        scroller_height,
        total_rows: screen.total_rows,
        visible_rows,
        row_height: screen.row_height.clamp(9, 64),
        tooltip,
        done_hovered: screen.done_hovered,
        done_focused: screen.done_focused,
    })
}

fn sanitize_hud_system_toast(toast: HudSystemToast) -> Option<HudSystemToast> {
    if !toast.visible_portion.is_finite() {
        return None;
    }
    let multiline = toast.multiline;
    let title = sanitize_hud_text_line(toast.title)?;
    let message = if multiline {
        let message = sanitize_hud_multiline_text(toast.message, 256);
        (!message.is_empty()).then_some(message)?
    } else {
        sanitize_hud_text_line(toast.message)?
    };
    (!title.is_empty() && !message.is_empty()).then_some(HudSystemToast {
        title,
        message,
        multiline,
        visible_portion: toast.visible_portion.clamp(0.0, 1.0),
    })
}

fn sanitize_hud_advancement_toast(toast: HudAdvancementToast) -> Option<HudAdvancementToast> {
    if !toast.visible_portion.is_finite() || usize::from(toast.slot) >= HUD_TOAST_SLOTS {
        return None;
    }
    let frame_label = sanitize_hud_text_line(toast.frame_label)?;
    let title = toast
        .title_runs
        .iter()
        .map(|run| run.text.as_str())
        .collect::<String>();
    let title = sanitize_hud_multiline_text(title, 256);
    let title_runs = sanitize_hud_multiline_styled_runs(toast.title_runs, &title);
    let icon = sanitize_hud_item_icon(toast.icon)?;
    (!frame_label.is_empty()).then_some(HudAdvancementToast {
        frame_label,
        frame_label_color: toast.frame_label_color & 0xFF_FF_FF,
        title_runs,
        icon,
        block_model: toast.block_model,
        slot: toast.slot,
        visible_portion: toast.visible_portion.clamp(0.0, 1.0),
        fully_visible_ms: toast.fully_visible_ms,
    })
}

fn sanitize_hud_recipe_toast(toast: HudRecipeToast) -> Option<HudRecipeToast> {
    if !toast.visible_portion.is_finite() || usize::from(toast.slot) >= HUD_TOAST_SLOTS {
        return None;
    }
    let title = sanitize_hud_text_line(toast.title)?;
    let description = sanitize_hud_text_line(toast.description)?;
    Some(HudRecipeToast {
        title,
        description,
        category_icon: toast.category_icon.and_then(sanitize_hud_item_icon),
        category_block_model: toast.category_block_model,
        unlocked_icon: toast.unlocked_icon.and_then(sanitize_hud_item_icon),
        unlocked_block_model: toast.unlocked_block_model,
        slot: toast.slot,
        visible_portion: toast.visible_portion.clamp(0.0, 1.0),
    })
}

fn sanitize_hud_tutorial_toast(toast: HudTutorialToast) -> Option<HudTutorialToast> {
    if !toast.visible_portion.is_finite()
        || toast.progress.is_some_and(|progress| !progress.is_finite())
        || usize::from(toast.slot) >= HUD_TOAST_SLOTS
    {
        return None;
    }
    let lines = toast
        .lines
        .into_iter()
        .take(64)
        .map(|runs| {
            let fallback = runs.iter().map(|run| run.text.as_str()).collect::<String>();
            let fallback = sanitize_hud_text_preserving_empty(fallback, 256);
            sanitize_hud_styled_runs(runs, &fallback)
        })
        .collect::<Vec<_>>();
    let height = tutorial_toast_height(lines.len());
    let occupied_slots = height.div_ceil(HUD_ADVANCEMENT_TOAST_HEIGHT);
    if usize::from(toast.slot).saturating_add(usize::try_from(occupied_slots).unwrap_or(usize::MAX))
        > HUD_TOAST_SLOTS
    {
        return None;
    }
    Some(HudTutorialToast {
        icon: toast.icon,
        lines,
        slot: toast.slot,
        visible_portion: toast.visible_portion.clamp(0.0, 1.0),
        progress: toast.progress.map(|progress| progress.clamp(0.0, 1.0)),
        progress_increasing: toast.progress_increasing,
    })
}

fn sanitize_hud_debug_options_screen(
    screen: HudDebugOptionsScreen,
) -> Option<HudDebugOptionsScreen> {
    let title = sanitize_hud_text_line(screen.title)?;
    let warning = sanitize_hud_text_line(screen.warning)?;
    let search_hint = sanitize_hud_text_line(screen.search_hint)?;
    let never_label = sanitize_hud_text_line(screen.never_label)?;
    let overlay_label = sanitize_hud_text_line(screen.overlay_label)?;
    let always_label = sanitize_hud_text_line(screen.always_label)?;
    let default_profile_label = sanitize_hud_text_line(screen.default_profile_label)?;
    let performance_profile_label = sanitize_hud_text_line(screen.performance_profile_label)?;
    let done_label = sanitize_hud_text_line(screen.done_label)?;
    let search_text = sanitize_hud_text_preserving_empty_utf16(screen.search_text, 32);
    let search_len = search_text.chars().count();
    let visible_rows = screen.visible_rows.min(64);
    let rows = screen
        .rows
        .into_iter()
        .filter_map(sanitize_hud_debug_options_row)
        .take(visible_rows)
        .collect::<Vec<_>>();
    let tooltip = screen.tooltip.and_then(sanitize_hud_debug_options_tooltip);
    (!title.is_empty()).then_some(HudDebugOptionsScreen {
        title,
        warning,
        search_cursor: screen.search_cursor.min(search_len),
        search_selection: screen.search_selection.min(search_len),
        search_cursor_visible: screen.search_cursor_visible,
        search_focused: screen.search_focused,
        search_hint,
        never_label,
        overlay_label,
        always_label,
        search_text,
        rows,
        tooltip,
        scroll_row: screen.scroll_row.min(screen.total_rows),
        total_rows: screen.total_rows.min(256),
        visible_rows,
        default_profile_active: screen.default_profile_active,
        default_profile_hovered: screen.default_profile_hovered,
        default_profile_focused: screen.default_profile_focused,
        default_profile_label,
        performance_profile_active: screen.performance_profile_active,
        performance_profile_hovered: screen.performance_profile_hovered,
        performance_profile_focused: screen.performance_profile_focused,
        performance_profile_label,
        done_hovered: screen.done_hovered,
        done_focused: screen.done_focused,
        done_label,
    })
}

fn sanitize_hud_debug_options_row(row: HudDebugOptionsRow) -> Option<HudDebugOptionsRow> {
    match row {
        HudDebugOptionsRow::Category { label } => {
            let label = sanitize_hud_text_line(label)?;
            Some(HudDebugOptionsRow::Category { label })
        }
        HudDebugOptionsRow::Entry {
            path,
            status,
            hovered_status,
            focused_status,
            allowed,
        } => {
            let path = sanitize_hud_text_line(path)?;
            Some(HudDebugOptionsRow::Entry {
                path,
                status,
                hovered_status,
                focused_status,
                allowed,
            })
        }
    }
}

fn sanitize_hud_debug_options_tooltip(
    tooltip: HudDebugOptionsTooltip,
) -> Option<HudDebugOptionsTooltip> {
    let text = sanitize_hud_text_line(tooltip.text)?;
    (!text.is_empty()).then_some(HudDebugOptionsTooltip {
        text,
        x: tooltip.x,
        y: tooltip.y,
    })
}

fn sanitize_hud_debug_game_mode_switcher_slot(
    slot: HudDebugGameModeSwitcherSlot,
) -> Option<HudDebugGameModeSwitcherSlot> {
    (slot.width > 0 && slot.height > 0).then_some(HudDebugGameModeSwitcherSlot {
        mode: slot.mode,
        x: slot.x,
        y: slot.y,
        width: slot.width,
        height: slot.height,
        selected: slot.selected,
        icon: slot.icon.and_then(sanitize_hud_item_icon),
        block_model: slot.block_model.filter(hud_block_item_model_is_renderable),
    })
}

fn sanitize_hud_debug_crosshair(crosshair: HudDebugCrosshair) -> Option<HudDebugCrosshair> {
    (crosshair.x_rot_degrees.is_finite() && crosshair.y_rot_degrees.is_finite()).then_some(
        HudDebugCrosshair {
            gui_scale: crosshair.gui_scale.max(1),
            ..crosshair
        },
    )
}

fn sanitize_hud_debug_profiler_chart(mut chart: HudDebugProfilerChart) -> HudDebugProfilerChart {
    chart.current_node_name = sanitize_hud_text_preserving_empty(chart.current_node_name, 128);
    if !chart.current_global_percentage.is_finite() {
        chart.current_global_percentage = 0.0;
    }
    chart.current_global_percentage = chart.current_global_percentage.clamp(0.0, 100.0);
    chart.slices = chart
        .slices
        .into_iter()
        .filter_map(sanitize_hud_debug_profiler_slice)
        .take(HUD_DEBUG_PROFILER_SLICE_CAPACITY)
        .collect();
    chart
}

fn sanitize_hud_debug_profiler_slice(
    mut slice: HudDebugProfilerSlice,
) -> Option<HudDebugProfilerSlice> {
    if !slice.percentage.is_finite() || !slice.global_percentage.is_finite() {
        return None;
    }
    slice.name = sanitize_hud_text_preserving_empty(slice.name, 128);
    slice.percentage = slice.percentage.clamp(0.0, 100.0);
    slice.global_percentage = slice.global_percentage.clamp(0.0, 100.0);
    Some(slice)
}

fn sanitize_hud_debug_fps_chart(mut chart: HudDebugFrameTimeChart) -> HudDebugFrameTimeChart {
    if chart.frame_time_nanos.len() > HUD_DEBUG_CHART_SAMPLE_CAPACITY {
        let keep_from = chart.frame_time_nanos.len() - HUD_DEBUG_CHART_SAMPLE_CAPACITY;
        chart.frame_time_nanos = chart.frame_time_nanos.split_off(keep_from);
    }
    if !matches!(chart.configured_framerate_limit, Some(1..=250)) {
        chart.configured_framerate_limit = None;
    }
    chart
}

fn sanitize_hud_debug_tps_chart(mut chart: HudDebugTpsChart) -> HudDebugTpsChart {
    if chart.samples.len() > HUD_DEBUG_CHART_SAMPLE_CAPACITY {
        let keep_from = chart.samples.len() - HUD_DEBUG_CHART_SAMPLE_CAPACITY;
        chart.samples = chart.samples.split_off(keep_from);
    }
    if !chart.milliseconds_per_tick.is_finite() || chart.milliseconds_per_tick <= 0.0 {
        chart.milliseconds_per_tick = 50.0;
    }
    chart
}

fn sanitize_hud_debug_network_charts(mut charts: HudDebugNetworkCharts) -> HudDebugNetworkCharts {
    if charts.ping_millis.len() > HUD_DEBUG_CHART_SAMPLE_CAPACITY {
        let keep_from = charts.ping_millis.len() - HUD_DEBUG_CHART_SAMPLE_CAPACITY;
        charts.ping_millis = charts.ping_millis.split_off(keep_from);
    }
    if charts.bandwidth_bytes_per_tick.len() > HUD_DEBUG_CHART_SAMPLE_CAPACITY {
        let keep_from = charts.bandwidth_bytes_per_tick.len() - HUD_DEBUG_CHART_SAMPLE_CAPACITY;
        charts.bandwidth_bytes_per_tick = charts.bandwidth_bytes_per_tick.split_off(keep_from);
    }
    charts
}

fn sanitize_hud_debug_overlay_lines(lines: Vec<String>) -> Vec<String> {
    lines
        .into_iter()
        .take(64)
        .map(|line| sanitize_hud_text_preserving_empty(line, 256))
        .collect()
}

fn sanitize_hud_text_line(line: String) -> Option<String> {
    let line = line
        .chars()
        .filter(|ch| !ch.is_control())
        .take(256)
        .collect::<String>();
    (!line.is_empty()).then_some(line)
}

fn sanitize_hud_text_preserving_empty(line: String, limit: usize) -> String {
    line.chars()
        .filter(|ch| !ch.is_control())
        .take(limit)
        .collect()
}

fn sanitize_hud_text_preserving_empty_utf16(line: String, limit: usize) -> String {
    let mut sanitized = String::new();
    let mut used = 0usize;
    for ch in line.chars().filter(|ch| !ch.is_control()) {
        let len = ch.len_utf16();
        if used.saturating_add(len) > limit {
            break;
        }
        sanitized.push(ch);
        used += len;
    }
    sanitized
}

fn sanitize_hud_multiline_text(line: String, limit: usize) -> String {
    let mut sanitized = String::new();
    let mut used = 0usize;
    for ch in line.chars().filter(|ch| *ch == '\n' || !ch.is_control()) {
        let len = ch.len_utf16();
        if used.saturating_add(len) > limit {
            break;
        }
        sanitized.push(ch);
        used += len;
    }
    sanitized
}

fn sanitize_hud_command_suggestions(mut state: HudCommandSuggestions) -> HudCommandSuggestions {
    let (max_length, max_entries, max_list_height) = match state.layout {
        HudCommandSuggestionsLayout::Chat => (256, 10, 120),
        HudCommandSuggestionsLayout::CommandBlock => (32_500, 7, 84),
    };
    state.input_text = sanitize_hud_text_preserving_empty_utf16(state.input_text, max_length);
    if state.layout == HudCommandSuggestionsLayout::CommandBlock {
        state.draft = false;
    }
    let text_len = state.input_text.chars().count();
    state.cursor = state.cursor.min(text_len);
    state.selection = state.selection.min(text_len);
    state.suffix = state
        .suffix
        .map(|suffix| sanitize_hud_text_preserving_empty_utf16(suffix, max_length))
        .filter(|suffix| !suffix.is_empty());
    state.list_width = state.list_width.min(4096);
    state.list_height = state.list_height.min(max_list_height);
    state.entries = state
        .entries
        .into_iter()
        .take(max_entries)
        .filter_map(|entry| {
            sanitize_hud_text_line(entry.text).map(|text| HudCommandSuggestionEntry {
                text,
                selected: entry.selected,
            })
        })
        .collect();
    state.tooltip = state.tooltip.and_then(|tooltip| {
        let fallback = tooltip
            .runs
            .iter()
            .map(|run| run.text.as_str())
            .collect::<String>();
        let fallback = sanitize_hud_text_line(fallback)?;
        Some(HudCommandSuggestionTooltip {
            runs: sanitize_hud_styled_runs(tooltip.runs, &fallback),
            x: tooltip.x,
            y: tooltip.y,
        })
    });
    state
}

fn sanitize_hud_chat_message(mut message: HudChatMessage) -> HudChatMessage {
    let fallback = message
        .runs
        .iter()
        .map(|run| run.visual.text.as_str())
        .collect::<String>();
    let fallback = sanitize_hud_multiline_text(fallback, 16_384);
    let mut message_budget = 16_384;
    message.runs = sanitize_hud_component_runs(message.runs, &fallback, &mut message_budget, true);
    let char_count = message
        .runs
        .iter()
        .map(|run| run.visual.text.chars().count())
        .sum();
    message.interactions.retain_mut(|interaction| {
        interaction.start_char = interaction.start_char.min(char_count);
        interaction.end_char = interaction.end_char.min(char_count);
        interaction.tooltip = interaction
            .tooltip
            .take()
            .and_then(sanitize_hud_rich_tooltip);
        interaction.start_char < interaction.end_char
    });
    if let Some(tag) = message.tag.as_mut() {
        let fallback = tag
            .tooltip_runs
            .iter()
            .map(|run| run.text.as_str())
            .collect::<String>();
        let fallback = sanitize_hud_multiline_text(fallback, 4_096);
        tag.tooltip_runs = sanitize_hud_chat_runs(std::mem::take(&mut tag.tooltip_runs), &fallback);
    }
    message
}

fn sanitize_hud_rich_tooltip(mut tooltip: HudRichTooltip) -> Option<HudRichTooltip> {
    tooltip.style = tooltip
        .style
        .map(|style| sanitize_hud_text_preserving_empty(style, 256))
        .filter(|style| !style.is_empty());
    let mut budget = 8_192usize;
    tooltip.lines = sanitize_hud_rich_tooltip_lines(tooltip.lines, &mut budget);
    tooltip.advanced_lines = tooltip
        .advanced_lines
        .map(|lines| sanitize_hud_rich_tooltip_lines(lines, &mut budget));
    let has_lines = !tooltip.lines.is_empty()
        || tooltip
            .advanced_lines
            .as_ref()
            .is_some_and(|lines| !lines.is_empty());
    has_lines.then_some(tooltip)
}

fn sanitize_hud_rich_tooltip_lines(
    lines: Vec<HudRichTooltipLine>,
    budget: &mut usize,
) -> Vec<HudRichTooltipLine> {
    lines
        .into_iter()
        .take(64)
        .map(|line| {
            let fallback = line
                .runs
                .iter()
                .map(|run| run.visual.text.as_str())
                .collect::<String>();
            let fallback = sanitize_hud_multiline_text(fallback, *budget);
            let tint = if line.tint.iter().all(|channel| channel.is_finite()) {
                line.tint.map(|channel| channel.clamp(0.0, 1.0))
            } else {
                HUD_TINT_WHITE
            };
            HudRichTooltipLine {
                runs: sanitize_hud_component_runs(line.runs, &fallback, budget, true),
                tint,
            }
        })
        .collect()
}

fn sanitize_hud_component_runs(
    runs: Vec<HudComponentTextRun>,
    fallback_text: &str,
    budget: &mut usize,
    allow_newline: bool,
) -> Vec<HudComponentTextRun> {
    let mut sanitized = Vec::new();
    for run in runs {
        if *budget == 0 {
            break;
        }
        let mut text = String::new();
        for ch in run
            .visual
            .text
            .chars()
            .filter(|ch| (allow_newline && *ch == '\n') || !ch.is_control())
        {
            let len = ch.len_utf16();
            if len > *budget {
                break;
            }
            text.push(ch);
            *budget -= len;
        }
        if !text.is_empty() {
            sanitized.push(HudComponentTextRun {
                visual: HudStyledTextRun {
                    text,
                    style: run.visual.style,
                    color: run.visual.color.map(|color| color & 0xFF_FF_FF),
                },
                font: run
                    .font
                    .map(|font| sanitize_hud_text_preserving_empty(font, 256))
                    .filter(|font| !font.is_empty()),
            });
        }
    }
    if sanitized.is_empty() && !fallback_text.is_empty() && *budget > 0 {
        let fallback = sanitize_hud_multiline_text(fallback_text.to_string(), *budget);
        *budget = (*budget).saturating_sub(fallback.encode_utf16().count());
        vec![HudComponentTextRun::plain(fallback)]
    } else {
        sanitized
    }
}

fn sanitize_hud_chat_runs(
    runs: Vec<HudStyledTextRun>,
    fallback_text: &str,
) -> Vec<HudStyledTextRun> {
    let mut budget = 16_384usize;
    let mut sanitized = Vec::new();
    for run in runs {
        if budget == 0 {
            break;
        }
        let mut text = String::new();
        for ch in run
            .text
            .chars()
            .filter(|ch| *ch == '\n' || !ch.is_control())
        {
            let len = ch.len_utf16();
            if len > budget {
                break;
            }
            text.push(ch);
            budget -= len;
        }
        if !text.is_empty() {
            sanitized.push(HudStyledTextRun {
                text,
                style: run.style,
                color: run.color.map(|color| color & 0xFF_FF_FF),
            });
        }
    }
    if sanitized.is_empty() && !fallback_text.is_empty() {
        vec![HudStyledTextRun::plain(fallback_text)]
    } else {
        sanitized
    }
}

/// Sanitizes a line's styled runs under the same rules as
/// [`sanitize_hud_text_line`] (control characters stripped, 256-char budget
/// across the line) and clamps run colours to `0xRRGGBB`. Empty run lists —
/// plain producers — synthesize a single default-style run from the already
/// sanitized `fallback_text`, so the draw loops always consume runs.
fn sanitize_hud_styled_runs(
    runs: Vec<HudStyledTextRun>,
    fallback_text: &str,
) -> Vec<HudStyledTextRun> {
    let mut budget = 256usize;
    let mut sanitized = Vec::new();
    for run in runs {
        if budget == 0 {
            break;
        }
        let text = run
            .text
            .chars()
            .filter(|ch| !ch.is_control())
            .take(budget)
            .collect::<String>();
        if text.is_empty() {
            continue;
        }
        budget -= text.chars().count();
        sanitized.push(HudStyledTextRun {
            text,
            style: run.style,
            color: run.color.map(|color| color & 0xFF_FF_FF),
        });
    }
    if sanitized.is_empty() {
        vec![HudStyledTextRun::plain(fallback_text)]
    } else {
        sanitized
    }
}

fn sanitize_hud_multiline_styled_runs(
    runs: Vec<HudStyledTextRun>,
    fallback_text: &str,
) -> Vec<HudStyledTextRun> {
    let mut budget = 256usize;
    let mut sanitized = Vec::new();
    for run in runs {
        if budget == 0 {
            break;
        }
        let mut text = String::new();
        for ch in run
            .text
            .chars()
            .filter(|ch| *ch == '\n' || !ch.is_control())
        {
            if budget == 0 {
                break;
            }
            text.push(ch);
            budget -= 1;
        }
        if !text.is_empty() {
            sanitized.push(HudStyledTextRun {
                text,
                style: run.style,
                color: run.color.map(|color| color & 0xFF_FF_FF),
            });
        }
    }
    if sanitized.is_empty() {
        vec![HudStyledTextRun::plain(fallback_text)]
    } else {
        sanitized
    }
}

/// Vanilla `ItemStack.setPopTime(5)` is the only value the client ever writes,
/// so a projected pop can never exceed five ticks.
const VANILLA_ITEM_POP_TIME_TICKS: f32 = 5.0;

fn sanitize_hud_item_icon(icon: HudItemIcon) -> Option<HudItemIcon> {
    if icon.lighting != GuiItemLightingEntry::ItemsFlat {
        return None;
    }
    let layers = icon
        .layers
        .into_iter()
        .filter_map(sanitize_hud_icon_layer)
        .collect::<Vec<_>>();
    (!layers.is_empty()).then_some(HudItemIcon {
        pop: if icon.pop.is_finite() {
            icon.pop.clamp(0.0, VANILLA_ITEM_POP_TIME_TICKS)
        } else {
            0.0
        },
        lighting: GuiItemLightingEntry::ItemsFlat,
        layers,
        foil: icon.foil,
        count_label: icon.count_label.and_then(sanitize_hud_item_count_label),
        durability_bar: icon
            .durability_bar
            .and_then(sanitize_hud_item_durability_bar),
        cooldown_progress: sanitize_hud_item_cooldown_progress(icon.cooldown_progress),
    })
}

fn sanitize_hud_icon_layer(layer: HudIconLayer) -> Option<HudIconLayer> {
    if !layer.tint.iter().all(|component| component.is_finite()) {
        return None;
    }
    Some(HudIconLayer {
        uv: sanitize_hud_uv_rect(layer.uv)?,
        tint: layer.tint.map(|component| component.clamp(0.0, 1.0)),
    })
}

fn sanitize_hud_item_count_label(label: HudItemCountLabel) -> Option<HudItemCountLabel> {
    let text = label.text;
    (!text.is_empty() && text.bytes().all(|byte| byte.is_ascii_digit()))
        .then_some(HudItemCountLabel { text })
}

fn sanitize_hud_item_durability_bar(bar: HudItemDurabilityBar) -> Option<HudItemDurabilityBar> {
    if !bar.color.iter().all(|component| component.is_finite()) {
        return None;
    }
    Some(HudItemDurabilityBar {
        width: bar.width.min(HUD_ITEM_BAR_BACKGROUND_WIDTH),
        color: bar.color.map(|component| component.clamp(0.0, 1.0)),
    })
}

fn sanitize_hud_item_cooldown_progress(progress: Option<f32>) -> Option<f32> {
    let progress = progress?;
    progress.is_finite().then_some(progress.clamp(0.0, 1.0))
}

