    fn hud_inventory_beacon_test_renderer() -> Option<Renderer> {
        const WIDTH: u32 = 230;
        const HEIGHT: u32 = 219;

        let mut renderer = Renderer::new_offscreen(WIDTH, HEIGHT)?;
        renderer.set_clear_color(ClearColor {
            r: 0.0,
            g: 0.0,
            b: 0.25,
            a: 1.0,
        });
        renderer.update_camera();
        renderer
            .upload_hud_beacon_background(1, 1, &[0, 0, 0, 0])
            .expect("transparent Beacon background");
        renderer
            .upload_hud_beacon_button_disabled(1, 1, &[255, 0, 0, 255])
            .expect("disabled Beacon button");
        renderer
            .upload_hud_beacon_button_selected(1, 1, &[0, 255, 0, 255])
            .expect("selected Beacon button");
        renderer
            .upload_hud_beacon_button_highlighted(1, 1, &[255, 255, 0, 255])
            .expect("highlighted Beacon button");
        renderer
            .upload_hud_beacon_button(1, 1, &[255, 0, 255, 255])
            .expect("normal Beacon button");
        renderer
            .upload_hud_beacon_confirm(1, 1, &[0, 255, 255, 255])
            .expect("Beacon confirm icon");
        renderer
            .upload_hud_beacon_cancel(1, 1, &[255, 255, 255, 255])
            .expect("Beacon cancel icon");
        let speed = [0, 255, 255, 255];
        let strength = [255, 255, 255, 255];
        renderer
            .upload_hud_mob_effect_sprites(&[(1, 1, 1, &speed), (5, 1, 1, &strength)])
            .expect("Beacon effect icons");

        let item_colors = [
            [255, 0, 0, 255],
            [0, 255, 0, 255],
            [0, 255, 255, 255],
            [255, 0, 255, 255],
            [255, 255, 255, 255],
        ];
        let item_atlas = item_colors.into_iter().flatten().collect::<Vec<_>>();
        renderer
            .upload_hud_item_atlas(5, 1, &item_atlas)
            .expect("Beacon payment item atlas");

        let background_layer = |texture: HudInventoryBackgroundTexture, x, y, width, height| {
            HudInventoryBackgroundLayer {
                texture,
                x,
                y,
                width,
                height,
                uv: HudUvRect {
                    min: [0.0, 0.0],
                    max: [1.0, 1.0],
                },
            }
        };
        let floating_items = [(20, 109), (41, 109), (63, 109), (86, 109), (108, 109)]
            .into_iter()
            .enumerate()
            .map(|(index, (x, y))| HudInventoryItem {
                x,
                y,
                scale: 1.0,
                scale_y: 1.0,
                icon: HudItemIcon::single(HudUvRect {
                    min: [index as f32 / 5.0, 0.0],
                    max: [(index + 1) as f32 / 5.0, 1.0],
                }),
                scissor: None,
                draw_decorations: false,
                block_model: None,
            })
            .collect();
        renderer.set_hud_inventory_screen(Some(HudInventoryScreen {
            width: WIDTH,
            height: HEIGHT,
            background_layers: vec![
                background_layer(HudInventoryBackgroundTexture::Beacon, 0, 0, WIDTH, HEIGHT),
                background_layer(
                    HudInventoryBackgroundTexture::BeaconButtonDisabled,
                    53,
                    22,
                    22,
                    22,
                ),
                background_layer(HudInventoryBackgroundTexture::MobEffect(1), 55, 24, 18, 18),
                background_layer(
                    HudInventoryBackgroundTexture::BeaconButtonSelected,
                    65,
                    72,
                    22,
                    22,
                ),
                background_layer(HudInventoryBackgroundTexture::MobEffect(5), 67, 74, 18, 18),
                background_layer(
                    HudInventoryBackgroundTexture::BeaconButtonHighlighted,
                    164,
                    107,
                    22,
                    22,
                ),
                background_layer(
                    HudInventoryBackgroundTexture::BeaconConfirm,
                    166,
                    109,
                    18,
                    18,
                ),
                background_layer(
                    HudInventoryBackgroundTexture::BeaconButton,
                    190,
                    107,
                    22,
                    22,
                ),
                background_layer(
                    HudInventoryBackgroundTexture::BeaconCancel,
                    192,
                    109,
                    18,
                    18,
                ),
            ],
            foreground_layers: Vec::new(),
            fill_layers: Vec::new(),
            slots: Vec::new(),
            floating_items,
            foreground_items: Vec::new(),
            ghost_items: Vec::new(),
            entity_previews: Vec::new(),
            map_previews: Vec::new(),
            banner_pattern_previews: Vec::new(),
            text_labels: Vec::new(),
            scroll_area: None,
            preedit_overlay: None,
            hovered_slot_id: None,
            tooltip: None,
        }));
        Some(renderer)
    }

    #[test]
    fn hud_inventory_beacon_draw_commands_preserve_button_icon_and_item_strata() {
        let Some(renderer) = hud_inventory_beacon_test_renderer() else {
            return;
        };
        let expected = vec![
            std::ptr::from_ref(renderer.hud_beacon_background.as_ref().unwrap()),
            std::ptr::from_ref(renderer.hud_beacon_button_disabled.as_ref().unwrap()),
            std::ptr::from_ref(renderer.hud_mob_effect_sprites.get(&1).unwrap()),
            std::ptr::from_ref(renderer.hud_beacon_button_selected.as_ref().unwrap()),
            std::ptr::from_ref(renderer.hud_mob_effect_sprites.get(&5).unwrap()),
            std::ptr::from_ref(renderer.hud_beacon_button_highlighted.as_ref().unwrap()),
            std::ptr::from_ref(renderer.hud_beacon_confirm.as_ref().unwrap()),
            std::ptr::from_ref(renderer.hud_beacon_button.as_ref().unwrap()),
            std::ptr::from_ref(renderer.hud_beacon_cancel.as_ref().unwrap()),
            std::ptr::from_ref(renderer.hud_item_atlas.as_ref().unwrap()),
            std::ptr::from_ref(renderer.hud_item_atlas.as_ref().unwrap()),
            std::ptr::from_ref(renderer.hud_item_atlas.as_ref().unwrap()),
            std::ptr::from_ref(renderer.hud_item_atlas.as_ref().unwrap()),
            std::ptr::from_ref(renderer.hud_item_atlas.as_ref().unwrap()),
        ];
        let draws = renderer.collect_hud_draws();
        let actual = draws
            .commands
            .iter()
            .filter_map(|command| match command {
                HudDrawCommand::Sprite { sprite, .. } => Some(std::ptr::from_ref(*sprite)),
                _ => None,
            })
            .filter(|sprite| expected.contains(sprite))
            .collect::<Vec<_>>();

        assert_eq!(actual, expected);
        assert_eq!(
            actual
                .iter()
                .filter(|sprite| {
                    **sprite == std::ptr::from_ref(renderer.hud_item_atlas.as_ref().unwrap())
                })
                .count(),
            5
        );
    }

    #[test]
    fn hud_inventory_beacon_offscreen_consumes_button_states_icons_and_payment_items() {
        let Some(mut renderer) = hud_inventory_beacon_test_renderer() else {
            return;
        };

        let pixels = renderer
            .render_offscreen_frame()
            .expect("Beacon inventory frame");
        for (position, expected) in [
            ((53, 22), [255, 0, 0]),
            ((65, 72), [0, 255, 0]),
            ((164, 107), [255, 255, 0]),
            ((190, 107), [255, 0, 255]),
            ((63, 32), [0, 255, 255]),
            ((75, 82), [255, 255, 255]),
            ((174, 117), [0, 255, 255]),
            ((200, 117), [255, 255, 255]),
        ] {
            let pixel = pixels.pixel(position.0, position.1);
            for channel in 0..3 {
                assert!(
                    pixel[channel].abs_diff(expected[channel]) < 16,
                    "Beacon pixel at {position:?} should be {expected:?}, got {pixel:?}"
                );
            }
        }

        for ((x, y), expected) in [
            ((28, 117), [255, 0, 0]),
            ((49, 117), [0, 255, 0]),
            ((71, 117), [0, 255, 255]),
            ((94, 117), [255, 0, 255]),
            ((116, 117), [255, 255, 255]),
        ] {
            let pixel = pixels.pixel(x, y);
            for channel in 0..3 {
                assert!(
                    pixel[channel].abs_diff(expected[channel]) < 24,
                    "Beacon payment pixel at ({x},{y}) should be {expected:?}, got {pixel:?}"
                );
            }
        }
    }

    fn test_hud_mob_effect(
        effect_id: i32,
        beneficial: bool,
        color: u32,
        duration_ticks: i32,
        ambient: bool,
        show_icon: bool,
    ) -> HudMobEffect {
        HudMobEffect {
            effect_id,
            beneficial,
            color,
            amplifier: 0,
            duration_ticks,
            ambient,
            show_icon,
            display_name: format!("Effect {effect_id}"),
            duration_text: "00:10".to_string(),
        }
    }

    fn hud_mob_effect_test_glyphs() -> HudFontGlyphMap {
        let mut glyphs = HudFontGlyphMap::new();
        for character in ' '..='~' {
            glyphs.insert_first_wins(
                character,
                HudAsciiGlyph {
                    advance: 6,
                    width: 5,
                    height: 8,
                    ..HudAsciiGlyph::default()
                },
            );
        }
        glyphs
    }

    #[test]
    fn hud_mob_effect_overlay_matches_vanilla_order_rows_and_icon_alpha() {
        let effects = vec![
            test_hud_mob_effect(1, true, 1, 100, false, true),
            test_hud_mob_effect(2, false, 2, 60, false, true),
            test_hud_mob_effect(3, true, 3, 200, false, true),
            test_hud_mob_effect(4, false, 4, 1_000, true, true),
            test_hud_mob_effect(5, true, 5, 2_000, false, false),
        ];

        let instances = hud_mob_effect_overlay_instances(PhysicalSize::new(320, 240), &effects);
        assert_eq!(
            instances
                .iter()
                .map(|instance| instance.effect_id)
                .collect::<Vec<_>>(),
            vec![4, 3, 1, 2]
        );
        assert_eq!(
            instances
                .iter()
                .map(|instance| { (instance.background.x as i32, instance.background.y as i32,) })
                .collect::<Vec<_>>(),
            vec![(295, 27), (295, 1), (270, 1), (270, 27)]
        );
        assert_eq!(instances[0].icon_alpha, 1.0);
        assert!((instances[1].icon_alpha - 0.5).abs() < 1e-6);
        assert!((instances[2].icon_alpha - 0.625).abs() < 1e-6);
        assert!((instances[3].icon_alpha - 0.675).abs() < 1e-6);
        assert_eq!(
            (
                instances[0].icon.x as i32,
                instances[0].icon.y as i32,
                instances[0].icon.width,
                instances[0].icon.height,
            ),
            (298, 30, 18, 18)
        );
    }

    #[test]
    fn hud_mob_effect_icon_alpha_matches_vanilla_ending_window_edges() {
        let mut effect = test_hud_mob_effect(1, true, 1, 201, false, true);
        assert_eq!(hud_mob_effect_icon_alpha(&effect), 1.0);
        effect.duration_ticks = 200;
        assert!((hud_mob_effect_icon_alpha(&effect) - 0.5).abs() < 1e-6);
        effect.duration_ticks = 0;
        assert!((hud_mob_effect_icon_alpha(&effect) - 0.25).abs() < 1e-6);
        effect.duration_ticks = -1;
        assert_eq!(hud_mob_effect_icon_alpha(&effect), 1.0);
        effect.duration_ticks = 0;
        effect.ambient = true;
        assert_eq!(hud_mob_effect_icon_alpha(&effect), 1.0);
    }

    #[test]
    fn hud_inventory_mob_effects_match_wide_compact_and_dense_layouts() {
        let screen = hud_inventory_screen_with_entity_previews(Vec::new());
        let glyphs = hud_mob_effect_test_glyphs();
        let mut effects = (0..6)
            .map(|index| {
                test_hud_mob_effect(
                    index,
                    index % 2 == 0,
                    index as u32,
                    20 * (index + 1),
                    false,
                    true,
                )
            })
            .collect::<Vec<_>>();

        let wide = hud_inventory_mob_effect_instances(
            PhysicalSize::new(500, 240),
            &screen,
            &effects,
            &glyphs,
        );
        assert_eq!(wide.len(), 6);
        assert_eq!(
            wide.iter()
                .map(|instance| instance.effect_id)
                .collect::<Vec<_>>(),
            vec![0, 1, 2, 3, 4, 5]
        );
        assert_eq!(
            (
                wide[0].background_x,
                wide[0].background_y,
                wide[0].background_width,
                wide[0].icon_x,
                wide[0].icon_y,
                wide[5].background_y,
            ),
            (340, 37, 87, 347, 44, 167)
        );
        assert_eq!(wide[0].name.as_deref(), Some("Effect 0"));
        assert_eq!(wide[0].duration.as_deref(), Some("00:10"));

        let compact = hud_inventory_mob_effect_instances(
            PhysicalSize::new(400, 240),
            &screen,
            &effects,
            &glyphs,
        );
        assert_eq!(
            (
                compact[0].background_x,
                compact[0].background_width,
                compact[0].icon_x,
                compact[0].name.as_deref(),
                compact[0].duration.as_deref(),
            ),
            (290, 32, 297, None, None)
        );

        effects[0].display_name = "Effect name too wide for the available panel".to_string();
        let clipped = hud_inventory_mob_effect_instances(
            PhysicalSize::new(420, 240),
            &screen,
            &effects,
            &glyphs,
        );
        let clipped_name = clipped[0].name.as_deref().expect("wide panel text");
        assert!(clipped_name.len() < effects[0].display_name.len());
        assert!(
            hud_plain_text_width(clipped_name, &glyphs)
                <= clipped[0]
                    .background_width
                    .saturating_sub(HUD_INVENTORY_EFFECT_TEXT_X_OFFSET as u32)
                    .saturating_sub(HUD_INVENTORY_EFFECT_SPACING as u32)
        );
    }

    #[test]
    fn preedit_overlay_sanitizes_bounds_and_draws_focused_underline_and_caret() {
        let sanitized = sanitize_hud_inventory_preedit_overlay(HudInventoryPreeditOverlay {
            text: "a\u{0007}bc".to_string(),
            focused_start: 2,
            focused_end: usize::MAX,
            caret: Some(usize::MAX),
            caret_visible: true,
            text_x: 20,
            text_y: 30,
            background_x: 15,
            background_y: 25,
            background_width: u32::MAX,
            background_height: u32::MAX,
        })
        .unwrap();
        assert_eq!(sanitized.text, "abc");
        assert_eq!((sanitized.focused_start, sanitized.focused_end), (2, 3));
        assert_eq!(sanitized.caret, Some(3));
        assert_eq!(
            (sanitized.background_width, sanitized.background_height),
            (2048, 512)
        );

        let Some(mut renderer) = Renderer::new_offscreen(320, 240) else {
            return;
        };
        let glyph = HudAsciiGlyph {
            uv: HudUvRect {
                min: [0.0, 0.0],
                max: [1.0, 1.0],
            },
            width: 1,
            height: 1,
            advance: 6,
            ascent: HUD_FONT_BASELINE,
            ..HudAsciiGlyph::default()
        };
        let mut glyphs = HudFontGlyphMap::new();
        for ch in "abc".chars() {
            glyphs.insert_first_wins(ch, glyph);
        }
        renderer
            .upload_hud_font_atlas(1, 1, &[255, 255, 255, 255], glyphs)
            .unwrap();
        let mut screen = hud_inventory_screen_with_entity_previews(Vec::new());
        screen.preedit_overlay = Some(HudInventoryPreeditOverlay {
            text: "abc".to_string(),
            focused_start: 1,
            focused_end: 2,
            caret: Some(2),
            caret_visible: true,
            text_x: 20,
            text_y: 30,
            background_x: 15,
            background_y: 25,
            background_width: 28,
            background_height: 19,
        });
        renderer.set_hud_inventory_screen(Some(screen));

        let draws = renderer.collect_hud_draws();
        assert_eq!(
            draws
                .commands
                .iter()
                .filter(|command| matches!(command, HudDrawCommand::Sprite { .. }))
                .count(),
            3,
            "one batched glyph draw, one focused underline, and one caret"
        );
        assert_eq!(
            draws
                .commands
                .iter()
                .filter_map(|command| match command {
                    HudDrawCommand::Sprite { start, end, .. } => Some(end - start),
                    _ => None,
                })
                .collect::<Vec<_>>(),
            [18, 6, 6]
        );
        assert_eq!(draws.vertices.len(), 5 * 6);
    }

    #[test]
    fn preedit_overlay_submits_after_screen_foreground_and_before_tooltips() {
        let source = include_str!("hud.rs");
        let collect_start = source
            .find("fn collect_hud_draws(")
            .expect("collect_hud_draws is defined");
        let collect_source = &source[collect_start..];
        let foreground = collect_source
            .find("HudInventoryFillStage::Foreground")
            .expect("screen foreground draw is submitted");
        let preedit = collect_source
            .find("push_hud_inventory_preedit_overlay(")
            .expect("preedit overlay is submitted");
        let tooltip = collect_source
            .find("push_hud_inventory_tooltip(")
            .expect("tooltip is submitted");
        assert!(foreground < preedit && preedit < tooltip);
    }

